import { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Play, Star } from 'lucide-react';
import type { WatchRecord } from '@/types';
import { DialColorSwatch } from './ui/DialColorSwatch';

interface EditModalProps {
  record: WatchRecord | null;
  open: boolean;
  onClose: () => void;
  onSave: (record: WatchRecord) => void;
}

const backdropVariants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1, transition: { duration: 0.2 } },
  exit: { opacity: 0, transition: { duration: 0.2 } },
};

const modalVariants = {
  hidden: { opacity: 0, scale: 0.95 },
  visible: {
    opacity: 1,
    scale: 1,
    transition: { duration: 0.3, ease: [0, 0, 0.2, 1] as [number, number, number, number] },
  },
  exit: {
    opacity: 0,
    scale: 0.95,
    transition: { duration: 0.2, ease: [0.4, 0, 1, 1] as [number, number, number, number] },
  },
};

const fieldVariants = {
  hidden: { opacity: 0, y: 8 },
  visible: (i: number) => ({
    opacity: 1,
    y: 0,
    transition: { delay: i * 0.03, duration: 0.3, ease: [0, 0, 0.2, 1] as [number, number, number, number] },
  }),
};

const brandOptions = ['PATEK PHILIPPE', 'ROLEX', 'AUDEMARS PIGUET', 'VACHERON CONSTANTIN', 'CARTIER', 'OMEGA', 'OTHER'];
const familyOptions = ['Nautilus', 'Aquanaut', 'Calatrava', 'Grand Complications', 'Complications', 'Gondolo', 'Twenty-4', 'Other'];
const conditionOptions = ['New', 'Used', 'Like New', 'Naked'];
const currencyOptions = ['USD', 'HKD', 'EUR', 'GBP'];
const boxPapersOptions = ['Full Set', 'Box Only', 'Papers Only', 'None', 'Unknown'];

export function EditModal({ record, open, onClose, onSave }: EditModalProps) {
  const [form, setForm] = useState<Partial<WatchRecord>>({});
  const [sellerRating, setSellerRating] = useState(3);

  useEffect(() => {
    if (record) {
      setForm({ ...record });
      setSellerRating(record.sellerRating);
    }
  }, [record]);

  // Lock body scroll
  useEffect(() => {
    if (open) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return () => { document.body.style.overflow = ''; };
  }, [open]);

  // Escape key
  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && open) onClose();
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [open, onClose]);

  const updateField = useCallback(<K extends keyof WatchRecord>(field: K, value: WatchRecord[K]) => {
    setForm((prev) => ({ ...prev, [field]: value }));
  }, []);

  const handleSave = useCallback(() => {
    if (!record) return;
    const updated: WatchRecord = {
      ...record,
      ...form,
      sellerRating,
    } as WatchRecord;
    onSave(updated);
  }, [record, form, sellerRating, onSave]);

  if (!record) return null;

  const inputClass =
    'w-full h-9 px-2.5 bg-bg-input border border-border-default rounded text-sm text-text-primary font-sans placeholder:text-text-muted focus:outline-none focus:border-gold-primary focus:ring-1 focus:ring-gold-primary/20 transition-colors';
  const labelClass = 'block text-[10px] text-text-secondary uppercase tracking-[0.04em] mb-1';

  return (
    <AnimatePresence>
      {open && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          {/* Backdrop */}
          <motion.div
            variants={backdropVariants}
            initial="hidden"
            animate="visible"
            exit="exit"
            className="absolute inset-0 bg-black/70"
            onClick={onClose}
          />

          {/* Modal Container */}
          <motion.div
            variants={modalVariants}
            initial="hidden"
            animate="visible"
            exit="exit"
            className="relative z-[110] w-full max-w-[600px] max-h-[90vh] bg-bg-card border border-border-active rounded-lg shadow-elevated shadow-gold overflow-hidden flex flex-col"
          >
            {/* Header */}
            <div className="flex items-center justify-between px-5 py-4 border-b border-border-default flex-shrink-0">
              <div>
                <h2 className="text-lg font-bold text-gold-primary">EDIT RECORD</h2>
                <p className="text-sm text-text-muted mt-0.5">
                  {record.reference || 'Unknown Reference'}
                </p>
              </div>
              <button
                onClick={onClose}
                className="w-8 h-8 flex items-center justify-center rounded-md text-text-muted hover:text-gold-primary hover:bg-bg-elevated transition-colors cursor-pointer"
                aria-label="Close modal"
              >
                <X size={20} />
              </button>
            </div>

            {/* Form Body */}
            <div className="flex-1 overflow-y-auto px-5 py-4">
              <div className="flex flex-col gap-4">
                {/* Field 1: Reference */}
                <motion.div custom={0} variants={fieldVariants} initial="hidden" animate="visible">
                  <label className={labelClass}>Reference Number</label>
                  <input
                    type="text"
                    value={form.reference ?? ''}
                    onChange={(e) => updateField('reference', e.target.value)}
                    className={`${inputClass} font-mono`}
                    placeholder="e.g. 5711/1A-010"
                  />
                </motion.div>

                {/* Field 2: Brand */}
                <motion.div custom={1} variants={fieldVariants} initial="hidden" animate="visible">
                  <label className={labelClass}>Brand</label>
                  <select
                    value={form.brand ?? ''}
                    onChange={(e) => updateField('brand', e.target.value)}
                    className={inputClass}
                  >
                    <option value="">Select brand...</option>
                    {brandOptions.map((b) => (
                      <option key={b} value={b}>{b}</option>
                    ))}
                  </select>
                </motion.div>

                {/* Field 3: Family */}
                <motion.div custom={2} variants={fieldVariants} initial="hidden" animate="visible">
                  <label className={labelClass}>Family</label>
                  <select
                    value={form.family ?? ''}
                    onChange={(e) => updateField('family', e.target.value as WatchRecord['family'])}
                    className={inputClass}
                  >
                    <option value="">Select family...</option>
                    {familyOptions.map((f) => (
                      <option key={f} value={f}>{f}</option>
                    ))}
                  </select>
                </motion.div>

                {/* Field 4: Dial Color */}
                <motion.div custom={3} variants={fieldVariants} initial="hidden" animate="visible">
                  <label className={labelClass}>Dial Color</label>
                  <div className="flex items-center gap-2">
                    <input
                      type="text"
                      value={form.dialColor ?? ''}
                      onChange={(e) => updateField('dialColor', e.target.value)}
                      className={`${inputClass} flex-1`}
                      placeholder="e.g. Blue"
                    />
                    {form.dialColor && <DialColorSwatch color={form.dialColor} size={20} showTooltip={false} />}
                  </div>
                </motion.div>

                {/* Field 5: Price */}
                <motion.div custom={4} variants={fieldVariants} initial="hidden" animate="visible">
                  <label className={labelClass}>Price (USD)</label>
                  <input
                    type="number"
                    value={form.price ?? ''}
                    onChange={(e) => updateField('price', Number(e.target.value))}
                    className={`${inputClass} font-mono`}
                    placeholder="0"
                    min={0}
                  />
                </motion.div>

                {/* Field 6: Currency */}
                <motion.div custom={5} variants={fieldVariants} initial="hidden" animate="visible">
                  <label className={labelClass}>Original Currency</label>
                  <select
                    value={form.originalCurrency ?? ''}
                    onChange={(e) => updateField('originalCurrency', e.target.value as WatchRecord['originalCurrency'])}
                    className={inputClass}
                  >
                    <option value="">Select currency...</option>
                    {currencyOptions.map((c) => (
                      <option key={c} value={c}>{c}</option>
                    ))}
                  </select>
                </motion.div>

                {/* Field 7: Year */}
                <motion.div custom={6} variants={fieldVariants} initial="hidden" animate="visible">
                  <label className={labelClass}>Year</label>
                  <input
                    type="number"
                    value={form.year ?? ''}
                    onChange={(e) => updateField('year', e.target.value ? Number(e.target.value) : null)}
                    className={`${inputClass} font-mono`}
                    placeholder="e.g. 2021"
                    min={1900}
                    max={2099}
                  />
                </motion.div>

                {/* Field 8: Condition */}
                <motion.div custom={7} variants={fieldVariants} initial="hidden" animate="visible">
                  <label className={labelClass}>Condition</label>
                  <select
                    value={form.condition ?? ''}
                    onChange={(e) => updateField('condition', e.target.value as WatchRecord['condition'])}
                    className={inputClass}
                  >
                    <option value="">Select condition...</option>
                    {conditionOptions.map((c) => (
                      <option key={c} value={c}>{c}</option>
                    ))}
                  </select>
                </motion.div>

                {/* Field 9: Box/Papers */}
                <motion.div custom={8} variants={fieldVariants} initial="hidden" animate="visible">
                  <label className={labelClass}>Box/Papers</label>
                  <select
                    value={
                      form.hasBox && form.hasPapers ? 'Full Set' :
                      form.hasBox ? 'Box Only' :
                      form.hasPapers ? 'Papers Only' :
                      form.hasBox === false && form.hasPapers === false ? 'None' : ''
                    }
                    onChange={(e) => {
                      const val = e.target.value;
                      updateField('hasBox', val === 'Full Set' || val === 'Box Only');
                      updateField('hasPapers', val === 'Full Set' || val === 'Papers Only');
                    }}
                    className={inputClass}
                  >
                    <option value="">Select...</option>
                    {boxPapersOptions.map((o) => (
                      <option key={o} value={o}>{o}</option>
                    ))}
                  </select>
                </motion.div>

                {/* Field 10: Seller Rating */}
                <motion.div custom={9} variants={fieldVariants} initial="hidden" animate="visible">
                  <label className={labelClass}>Seller Rating</label>
                  <div className="flex items-center gap-2">
                    <div className="flex items-center gap-1">
                      {[1, 2, 3, 4, 5].map((star) => (
                        <button
                          key={star}
                          type="button"
                          onClick={() => setSellerRating(star)}
                          className="p-0.5 cursor-pointer transition-transform hover:scale-110"
                        >
                          <Star
                            size={18}
                            className={star <= sellerRating ? 'text-gold-primary fill-gold-primary' : 'text-bg-elevated'}
                          />
                        </button>
                      ))}
                    </div>
                    <span className="text-xs font-mono text-text-secondary ml-2">{sellerRating}/5</span>
                  </div>
                </motion.div>

                {/* Field 11: Source Line */}
                <motion.div custom={10} variants={fieldVariants} initial="hidden" animate="visible">
                  <label className={labelClass}>Source Message</label>
                  <textarea
                    value={form.rawMessage ?? ''}
                    onChange={(e) => updateField('rawMessage', e.target.value)}
                    className={`${inputClass} h-20 py-2 resize-none font-mono text-xs`}
                    placeholder="Raw WhatsApp message..."
                    rows={3}
                  />
                </motion.div>

                {/* Field 12: Notes */}
                <motion.div custom={11} variants={fieldVariants} initial="hidden" animate="visible">
                  <label className={labelClass}>Notes</label>
                  <textarea
                    value={(form as Record<string, unknown>).notes as string ?? ''}
                    onChange={(e) => updateField('rawMessage' as keyof WatchRecord, e.target.value as WatchRecord[keyof WatchRecord])}
                    className={`${inputClass} h-16 py-2 resize-none`}
                    placeholder="Optional notes..."
                    rows={2}
                  />
                </motion.div>
              </div>
            </div>

            {/* Footer */}
            <div className="flex items-center justify-end gap-2 px-5 py-4 border-t border-border-default flex-shrink-0">
              <button
                onClick={onClose}
                className="px-4 py-2 rounded text-sm font-medium bg-bg-elevated text-text-secondary border border-border-default hover:bg-bg-card hover:text-text-primary transition-colors cursor-pointer"
              >
                Cancel
              </button>
              <button
                onClick={handleSave}
                className="inline-flex items-center gap-1.5 px-4 py-2 rounded text-sm font-semibold bg-gold-primary text-bg-primary hover:bg-gold-bright transition-colors cursor-pointer"
              >
                <Play size={14} />
                Save & Re-run Pipeline
              </button>
            </div>
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
}

import { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Radio, Loader2 } from 'lucide-react';

interface LiveRecord {
  id: string;
  raw_message: string;
  brand: string;
  reference: string;
  dial_color: string;
  price_raw: number;
  price_usd: number;
  currency: string;
  year: number | null;
  condition: string;
  confidence: number;
  verdict: string;
  source: string;
  channel_id: string;
  llm_used: boolean;
  received_at: string;
}

const VERDICT_STYLES: Record<string, { dot: string; chip: string; label: string }> = {
  APPROVED: { dot: 'bg-green-500', chip: 'bg-green-950/60 text-green-300 border-green-800', label: 'APPROVED' },
  HUMAN: { dot: 'bg-red-500', chip: 'bg-red-950/60 text-red-300 border-red-800', label: 'HUMAN' },
  RECYCLE: { dot: 'bg-gray-500', chip: 'bg-gray-900/60 text-gray-400 border-gray-700', label: 'RECYCLE' },
};

function fmtPrice(price: number, currency: string) {
  if (!price) return 'ΓÇö';
  return `${currency} ${price.toLocaleString()}`;
}

function timeAgo(iso: string) {
  const t = new Date(iso).getTime();
  const diff = Date.now() - t;
  if (diff < 60_000) return `${Math.floor(diff / 1000)}s ago`;
  if (diff < 3_600_000) return `${Math.floor(diff / 60_000)}m ago`;
  if (diff < 86_400_000) return `${Math.floor(diff / 3_600_000)}h ago`;
  return `${Math.floor(diff / 86_400_000)}d ago`;
}

export default function LiveStream() {
  const [records, setRecords] = useState<LiveRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [lastFetch, setLastFetch] = useState<Date | null>(null);
  const [newCount, setNewCount] = useState(0);
  const seenIds = useRef<Set<string>>(new Set());

  const fetchRecords = async (silent = false) => {
    try {
      if (!silent) setLoading(true);
      const res = await fetch('/api/ingest');
      const data = await res.json();
      const newRecs: LiveRecord[] = data.records || [];
      // Detect new ones
      let added = 0;
      for (const r of newRecs) {
        if (!seenIds.current.has(r.id)) {
          seenIds.current.add(r.id);
          added++;
        }
      }
      setRecords(newRecs);
      if (silent && added > 0) setNewCount((c) => c + added);
      setLastFetch(new Date());
      setError(null);
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRecords();
    const interval = setInterval(() => fetchRecords(true), 5000);
    return () => clearInterval(interval);
  }, []);

  return (
    <motion.section
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      className="px-5 mt-4"
    >
      <div className="flex items-center justify-between mb-3">
        <h2 className="text-xs font-bold uppercase tracking-[0.08em] text-gold-primary flex items-center gap-2">
          <Radio className="w-3.5 h-3.5 text-green-400 animate-pulse" />
          LIVE STREAM
          <span className="ml-2 text-[10px] text-gray-500 font-normal normal-case tracking-normal">
            Supabase ┬╖ {lastFetch ? `${lastFetch.toLocaleTimeString()}` : 'connecting...'}
          </span>
          {newCount > 0 && (
            <motion.span
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              className="ml-1 px-1.5 py-0.5 rounded-full bg-green-600 text-white text-[10px] font-bold"
            >
              +{newCount} new
            </motion.span>
          )}
        </h2>
        <div className="flex items-center gap-3">
          <span className="text-[10px] text-gray-500">
            {records.length} records
          </span>
          <button
            onClick={() => { fetchRecords(); setNewCount(0); }}
            disabled={loading}
            className="text-[10px] text-gold-primary hover:underline flex items-center gap-1"
          >
            {loading ? <Loader2 className="w-3 h-3 animate-spin" /> : 'Γå╗'} refresh
          </button>
        </div>
      </div>

      {error && (
        <div className="text-xs text-red-400 bg-red-950/30 border border-red-900 rounded p-2 mb-3">
          ΓÜá Live stream unavailable: {error}
        </div>
      )}

      <div
        className="rounded-lg border p-3 max-h-[480px] overflow-y-auto"
        style={{ backgroundColor: '#0a0a0a', borderColor: '#1f1f1f' }}
      >
        {records.length === 0 && !loading && (
          <div className="text-center text-gray-500 text-xs py-8">
            No live records yet.
            <br />
            <span className="text-[10px]">
              Messages from WhatsApp / Telegram dealers will appear here in real time.
            </span>
          </div>
        )}

        <AnimatePresence initial={false}>
          {records.map((r, idx) => {
            const v = VERDICT_STYLES[r.verdict] || VERDICT_STYLES.RECYCLE;
            return (
              <motion.div
                key={r.id}
                initial={{ opacity: 0, x: -20, backgroundColor: '#1a3a1a' }}
                animate={{ opacity: 1, x: 0, backgroundColor: '#0a0a0a' }}
                exit={{ opacity: 0 }}
                transition={{ duration: 0.4, delay: idx < 3 ? idx * 0.05 : 0 }}
                className="flex items-start gap-3 py-2.5 px-2 border-b border-[#1a1a1a] last:border-b-0"
              >
                <div className={`w-2 h-2 rounded-full mt-1.5 shrink-0 ${v.dot}`} />

                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-xs font-mono text-gray-400">
                      {timeAgo(r.received_at)}
                    </span>
                    <span
                      className={`text-[10px] px-1.5 py-0.5 rounded border font-semibold ${v.chip}`}
                    >
                      {v.label}
                    </span>
                    {r.llm_used && (
                      <span className="text-[9px] px-1 py-0.5 rounded bg-purple-950/60 text-purple-300 border border-purple-800">
                        AI
                      </span>
                    )}
                    <span className="text-[9px] text-gray-600 uppercase">
                      via {r.source}
                    </span>
                  </div>

                  <div className="text-sm text-gray-200 truncate" title={r.raw_message}>
                    {r.raw_message}
                  </div>

                  <div className="flex items-center gap-3 mt-1 text-[11px] text-gray-400 flex-wrap">
                    <span style={{ color: r.brand && r.brand !== 'Unknown' ? '#d4af37' : '#666' }}>
                      {r.brand || '?'}
                    </span>
                    {r.reference && <span className="text-gray-300">{r.reference}</span>}
                    {r.dial_color && <span>{r.dial_color}</span>}
                    {r.price_raw > 0 && (
                      <span className="text-green-400">
                        {fmtPrice(r.price_raw, r.currency)}
                        {r.price_usd && r.currency !== 'USD' && (
                          <span className="text-gray-500 ml-1">Γëê ${r.price_usd.toLocaleString()}</span>
                        )}
                      </span>
                    )}
                    {r.year && <span className="text-gray-500">{r.year}</span>}
                    <span className="ml-auto text-[10px] text-gray-600">
                      conf {r.confidence}%
                    </span>
                  </div>
                </div>
              </motion.div>
            );
          })}
        </AnimatePresence>
      </div>
    </motion.section>
  );
}

import { useState, useCallback, useMemo } from 'react';
import {
  Brain,
  Save, RefreshCw, X, CheckCircle2,
  Wand2, Database, Layers, Activity,
} from 'lucide-react';
import {
  computeFeatureScores, scoreColors,
  FEATURE_LABELS, type CatalogComparison, type FeatureScores,
} from '@/types/catalog';

// Re-export for backward compat
export { computeFeatureScores, FEATURE_LABELS, scoreColors };
export type { CatalogComparison, FeatureScores };

// ΓöÇΓöÇ Re-launched record after human edits ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
interface EditedRecord {
  brand: string;
  reference: string;
  dialColor: string;
  condition: string;
  price: number;
  currency: string;
  year: number | null;
  notes?: string;
}

interface Props {
  result: any;
  onRelaunch: (edited: EditedRecord) => Promise<void>;
  onAIReview: (msg: string) => Promise<any>;
  onClose: () => void;
  catalogs: CatalogComparison;
}



// ΓöÇΓöÇ AI co-pilot panel for records the parser can't handle ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
function AICopilot({
  rawMessage,
  onSuggest,
  onClose,
  onAIReview,
}: {
  rawMessage: string;
  onSuggest: (parsed: any) => void;
  onClose: () => void;
  onAIReview: (msg: string) => Promise<any>;
}) {
  const [thinking, setThinking] = useState(false);
  const [hint, setHint] = useState<string | null>(null);

  const askCoPilot = useCallback(async () => {
    setThinking(true);
    setHint(null);
    try {
      const parsed = await onAIReview(rawMessage);
      if (parsed) {
        const display = JSON.stringify(parsed, null, 2);
        setHint(display);
        onSuggest(parsed);
      }
    } catch (e: any) {
      setHint(`Error: ${e.message}`);
    } finally {
      setThinking(false);
    }
  }, [rawMessage, onAIReview, onSuggest]);

  return (
    <div className="rounded-lg p-3 mt-3" style={{ backgroundColor: '#0f172a', border: '1px solid #1e3a5f' }}>
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-2">
          <Wand2 className="w-4 h-4 text-purple-400" />
          <span className="text-xs font-bold text-purple-300">AI CO-PILOT (GPT-4o-mini)</span>
        </div>
        <button onClick={onClose} className="text-gray-500 hover:text-white">
          <X className="w-3.5 h-3.5" />
        </button>
      </div>
      <p className="text-[11px] text-gray-400 mb-2">
        The parser couldn't fully understand this. Let GPT-4o-mini analyze it and suggest fields for you to confirm.
      </p>
      <button
        onClick={askCoPilot}
        disabled={thinking}
        className="px-3 py-1.5 rounded-lg text-xs font-semibold disabled:opacity-50"
        style={{ backgroundColor: '#581c87', color: '#e9d5ff' }}
      >
        {thinking ? (
          <span className="inline-flex items-center gap-1.5">
            <span className="animate-spin w-3 h-3 border-2 rounded-full inline-block" style={{ borderColor: '#e9d5ff', borderTopColor: 'transparent' }} />
            Analyzing...
          </span>
        ) : (
          <><Brain className="inline w-3 h-3 mr-1" />Ask AI to interpret</>
        )}
      </button>
      {hint && (
        <pre className="mt-3 p-2 rounded text-[10px] font-mono overflow-x-auto whitespace-pre-wrap" style={{ backgroundColor: '#020617', color: '#a5b4fc' }}>
          {hint}
        </pre>
      )}
    </div>
  );
}

// ΓöÇΓöÇ Editable fields panel for human-in-the-loop ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
function EditFields({
  initial,
  onSave,
  onCancel,
  aiSuggestion,
}: {
  result: any;
  initial: EditedRecord;
  onSave: (r: EditedRecord) => void;
  onCancel: () => void;
  aiSuggestion?: any;
}) {
  const [edit, setEdit] = useState<EditedRecord>(initial);

  const upd = (k: keyof EditedRecord, v: any) => setEdit(prev => ({ ...prev, [k]: v }));

  // Apply AI suggestion to all fields
  const applyAI = () => {
    if (!aiSuggestion) return;
    const updated: any = { ...edit };
    if (aiSuggestion.brand) updated.brand = aiSuggestion.brand;
    if (aiSuggestion.reference) updated.reference = aiSuggestion.reference;
    if (aiSuggestion.dialColor) updated.dialColor = aiSuggestion.dialColor;
    if (aiSuggestion.condition) updated.condition = aiSuggestion.condition;
    if (aiSuggestion.price) updated.price = Number(aiSuggestion.price);
    if (aiSuggestion.currency) updated.currency = aiSuggestion.currency;
    if (aiSuggestion.year) updated.year = Number(aiSuggestion.year);
    setEdit(updated);
  };

  const fieldClass = "w-full px-2 py-1.5 rounded text-xs font-mono outline-none";
  const fieldStyle = { backgroundColor: '#0a0a0a', color: '#e8e8e8', border: '1px solid #333' };

  return (
    <div className="mt-3 p-3 rounded-lg" style={{ backgroundColor: '#111', border: '1px solid #333' }}>
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-2">
          <Save className="w-3.5 h-3.5 text-yellow-400" />
          <span className="text-xs font-bold text-yellow-300">EDIT FIELDS ΓÇö then re-launch</span>
        </div>
        <div className="flex gap-2">
          {aiSuggestion && (
            <button onClick={applyAI} className="text-[10px] px-2 py-1 rounded font-semibold" style={{ backgroundColor: '#581c87', color: '#e9d5ff' }}>
              Apply AI Suggestion
            </button>
          )}
          <button onClick={onCancel} className="text-[10px] px-2 py-1 rounded text-gray-400 hover:text-white">
            Cancel
          </button>
          <button onClick={() => onSave(edit)} className="text-[10px] px-2 py-1 rounded font-bold" style={{ backgroundColor: '#d4af37', color: '#050505' }}>
            Save + Re-launch ΓåÆ
          </button>
        </div>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
        <div>
          <label className="text-[9px] uppercase tracking-wide text-gray-500">Brand</label>
          <input value={edit.brand} onChange={e => upd('brand', e.target.value)} className={fieldClass} style={fieldStyle} />
        </div>
        <div>
          <label className="text-[9px] uppercase tracking-wide text-gray-500">Reference</label>
          <input value={edit.reference} onChange={e => upd('reference', e.target.value.toUpperCase())} className={fieldClass} style={fieldStyle} />
        </div>
        <div>
          <label className="text-[9px] uppercase tracking-wide text-gray-500">Dial</label>
          <input value={edit.dialColor} onChange={e => upd('dialColor', e.target.value)} className={fieldClass} style={fieldStyle} />
        </div>
        <div>
          <label className="text-[9px] uppercase tracking-wide text-gray-500">Condition</label>
          <input value={edit.condition} onChange={e => upd('condition', e.target.value)} className={fieldClass} style={fieldStyle} />
        </div>
        <div>
          <label className="text-[9px] uppercase tracking-wide text-gray-500">Price</label>
          <input type="number" value={edit.price} onChange={e => upd('price', Number(e.target.value))} className={fieldClass} style={fieldStyle} />
        </div>
        <div>
          <label className="text-[9px] uppercase tracking-wide text-gray-500">Currency</label>
          <input value={edit.currency} onChange={e => upd('currency', e.target.value.toUpperCase())} className={fieldClass} style={fieldStyle} />
        </div>
        <div>
          <label className="text-[9px] uppercase tracking-wide text-gray-500">Year</label>
          <input type="number" value={edit.year || ''} onChange={e => upd('year', e.target.value ? Number(e.target.value) : null)} className={fieldClass} style={fieldStyle} />
        </div>
        <div>
          <label className="text-[9px] uppercase tracking-wide text-gray-500">Notes</label>
          <input value={edit.notes || ''} onChange={e => upd('notes', e.target.value)} className={fieldClass} style={fieldStyle} placeholder="optional" />
        </div>
      </div>
    </div>
  );
}

// ΓöÇΓöÇ 3-catalog comparison view ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
function CatalogComparisonView({ catalogs }: { catalogs: CatalogComparison }) {
  const rows = [
    {
      icon: Database, color: '#22c55e', name: catalogs.internal.name,
      field1: catalogs.internal.hit ? `Γ£ô ${catalogs.internal.brand}` : 'ΓÇö no match',
      field2: catalogs.internal.model || 'ΓÇö',
      field3: catalogs.internal.collection || 'ΓÇö',
      field4: `${catalogs.internal.size} total refs`,
      hit: catalogs.internal.hit,
    },
    {
      icon: Brain, color: '#a855f7', name: catalogs.llm.name,
      field1: catalogs.llm.brand ? `${catalogs.llm.brand}` : 'ΓÇö',
      field2: catalogs.llm.reference ? `${catalogs.llm.reference}` : 'ΓÇö',
      field3: catalogs.llm.model || 'ΓÇö',
      field4: `${Math.round(catalogs.llm.confidence * 100)}% confidence`,
      hit: catalogs.llm.confidence >= 0.7,
    },
    {
      icon: Layers, color: '#60a5fa', name: catalogs.dataset.name,
      field1: catalogs.dataset.sampleCount ? `${catalogs.dataset.sampleCount} similar` : 'ΓÇö unique',
      field2: catalogs.dataset.avgPrice ? `$${catalogs.dataset.avgPrice.toLocaleString()}` : 'ΓÇö',
      field3: catalogs.dataset.commonDial || 'ΓÇö',
      field4: catalogs.dataset.maxPrice ? `max $${catalogs.dataset.maxPrice.toLocaleString()}` : 'ΓÇö',
      hit: catalogs.dataset.sampleCount > 0,
    },
  ];

  return (
    <div className="rounded-lg p-3 mt-3" style={{ backgroundColor: '#0a0a0a', border: '1px solid #1f1f1f' }}>
      <div className="flex items-center gap-2 mb-3">
        <Layers className="w-4 h-4 text-blue-400" />
        <span className="text-xs font-bold text-blue-300">3-CATALOG COMPARISON</span>
      </div>
      <div className="grid grid-cols-1 gap-2">
        {rows.map((r, i) => {
          const Icon = r.icon;
          return (
            <div key={i} className="flex items-center gap-2 p-2 rounded" style={{ backgroundColor: '#111', border: `1px solid ${r.hit ? r.color + '44' : '#222'}` }}>
              <Icon className="w-4 h-4 shrink-0" style={{ color: r.color }} />
              <div className="flex-1 grid grid-cols-4 gap-2 text-[11px]">
                <div>
                  <div className="text-[9px] uppercase tracking-wide text-gray-500">Source</div>
                  <div className="font-semibold" style={{ color: r.color }}>{r.name}</div>
                </div>
                <div>
                  <div className="text-[9px] uppercase tracking-wide text-gray-500">Brand/Ref</div>
                  <div className="font-mono truncate" style={{ color: r.hit ? '#e8e8e8' : '#666' }}>{r.field1}</div>
                </div>
                <div>
                  <div className="text-[9px] uppercase tracking-wide text-gray-500">Model</div>
                  <div className="truncate" style={{ color: r.hit ? '#e8e8e8' : '#666' }}>{r.field2}</div>
                </div>
                <div>
                  <div className="text-[9px] uppercase tracking-wide text-gray-500">Context</div>
                  <div className="truncate" style={{ color: '#888' }}>{r.field4}</div>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ΓöÇΓöÇ Per-feature confidence 1-10 grid ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
function FeatureScoreGrid({ scores }: { scores: FeatureScores }) {
  const features = (Object.keys(FEATURE_LABELS) as Array<keyof FeatureScores>).filter(k => k !== 'overall');
  return (
    <div className="rounded-lg p-3 mt-3" style={{ backgroundColor: '#0a0a0a', border: '1px solid #1f1f1f' }}>
      <div className="flex items-center gap-2 mb-2">
        <Activity className="w-4 h-4 text-yellow-400" />
        <span className="text-xs font-bold text-yellow-300">PER-FEATURE CONFIDENCE (1-10)</span>
        <span className="ml-auto text-xs font-mono" style={{ color: scoreColors(scores.overall).fg }}>
          OVERALL: {scores.overall}/10 {scoreColors(scores.overall).label}
        </span>
      </div>
      <div className="grid grid-cols-3 sm:grid-cols-6 gap-2">
        {features.map(k => {
          const v = scores[k];
          const c = scoreColors(v);
          return (
            <div key={k} className="p-2 rounded text-center" style={{ backgroundColor: c.bg, border: `1px solid ${c.border}` }}>
              <div className="text-[9px] uppercase tracking-wide truncate" style={{ color: '#aaa' }}>{FEATURE_LABELS[k]}</div>
              <div className="text-base font-bold font-mono" style={{ color: c.fg }}>{v}</div>
              <div className="text-[8px]" style={{ color: c.fg }}>{c.label}</div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ΓöÇΓöÇ Main TestModePanel ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export default function TestModePanel(props: Props) {
  const { result, onRelaunch, onAIReview, onClose, catalogs } = props;
  const [editing, setEditing] = useState(false);
  const [aiSuggestion, setAiSuggestion] = useState<any>(null);
  const [showCopilot, setShowCopilot] = useState(false);

  const initial: EditedRecord = useMemo(() => ({
    brand: result.brand || 'Unknown',
    reference: result.reference || '',
    dialColor: result.dialColor || 'UNKNOWN',
    condition: result.condition || 'Unknown',
    price: result.price || 0,
    currency: result.currency || '',
    year: result.year || null,
    notes: '',
  }), [result]);

  const scores = useMemo(() => computeFeatureScores(result, catalogs), [result, catalogs]);

  const handleSave = useCallback(async (edited: EditedRecord) => {
    await onRelaunch(edited);
    setEditing(false);
  }, [onRelaunch]);

  const handleAISuggest = useCallback((parsed: any) => {
    setAiSuggestion(parsed);
  }, []);

  const relaunch = useCallback(async () => {
    await onRelaunch(initial);
  }, [onRelaunch, initial]);

  // Don't show this panel for already-approved records (unless manually opened)
  const verdictColor = result.verdict === 'APPROVED' || result.verdict === 'AUTO_APPROVED'
    ? '#22c55e' : result.verdict === 'RECYCLE' ? '#ef4444' : '#eab308';
  const verdictLabel = result.verdict === 'AUTO_APPROVED' ? 'APPROVED' : result.verdict;

  return (
    <div className="rounded-xl p-4 my-3" style={{ backgroundColor: '#050505', border: `1px solid ${verdictColor}66` }}>
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-3">
          <div className="px-2 py-1 rounded text-[10px] font-bold uppercase tracking-wider"
            style={{ backgroundColor: `${verdictColor}22`, color: verdictColor, border: `1px solid ${verdictColor}66` }}>
            {verdictLabel}
          </div>
          <span className="text-xs text-gray-400">Confidence: <span className="font-mono font-bold" style={{ color: verdictColor }}>{result.confidence}%</span></span>
          <span className="text-xs text-gray-500 truncate max-w-[300px]" title={result.rawMessage}>
            "{result.rawMessage.slice(0, 80)}{result.rawMessage.length > 80 ? '...' : ''}"
          </span>
        </div>
        <button onClick={onClose} className="text-gray-500 hover:text-white">
          <X className="w-4 h-4" />
        </button>
      </div>

      <FeatureScoreGrid scores={scores} />
      <CatalogComparisonView catalogs={catalogs} />

      {/* Action panel ΓÇö only show for non-APPROVED verdicts OR if user wants to refine */}
      {(result.verdict !== 'APPROVED' && result.verdict !== 'AUTO_APPROVED') || editing ? (
        <div className="mt-3">
          {!editing ? (
            <div className="flex flex-wrap gap-2 items-center">
              <button onClick={() => setEditing(true)}
                className="px-4 py-2 rounded-lg text-xs font-semibold flex items-center gap-1.5"
                style={{ backgroundColor: '#422006', color: '#eab308', border: '1px solid #854d0e' }}>
                <Save className="w-3.5 h-3.5" /> Edit fields + Re-launch
              </button>
              <button onClick={() => setShowCopilot(s => !s)}
                className="px-4 py-2 rounded-lg text-xs font-semibold flex items-center gap-1.5"
                style={{ backgroundColor: '#1e1b4b', color: '#a5b4fc', border: '1px solid #312e81' }}>
                <Wand2 className="w-3.5 h-3.5" /> {showCopilot ? 'Hide AI Co-pilot' : 'Ask AI Co-pilot'}
              </button>
              <button onClick={relaunch}
                className="px-4 py-2 rounded-lg text-xs font-semibold flex items-center gap-1.5"
                style={{ backgroundColor: '#0f172a', color: '#60a5fa', border: '1px solid #1e3a5f' }}>
                <RefreshCw className="w-3.5 h-3.5" /> Just Re-launch
              </button>
              <div className="ml-auto text-[10px] text-gray-500 italic">
                Γå╗ Loop back to initial pipeline after edits
              </div>
            </div>
          ) : (
            <EditFields
              result={result}
              initial={initial}
              onSave={handleSave}
              onCancel={() => setEditing(false)}
              aiSuggestion={aiSuggestion}
            />
          )}

          {showCopilot && !editing && (
            <AICopilot
              rawMessage={result.rawMessage || ''}
              onSuggest={handleAISuggest}
              onClose={() => setShowCopilot(false)}
              onAIReview={onAIReview}
            />
          )}
        </div>
      ) : (
        <div className="mt-3 flex items-center gap-2 text-[11px]" style={{ color: '#22c55e' }}>
          <CheckCircle2 className="w-3.5 h-3.5" />
          <span>Record approved at {result.confidence}% ΓÇö no human review needed.</span>
        </div>
      )}
    </div>
  );
}

