function escapeCsv(val: any): string {
  if (val === null || val === undefined) return '';
  const s = String(val);
  if (s.includes(',') || s.includes('"') || s.includes('\n') || s.includes('\r')) {
    return '"' + s.replace(/"/g, '""') + '"';
  }
  return s;
}

export function exportCleanCsv(watches: CleanWatch[], _summary: any) {
  const rows: string[] = [];

  // Header
  rows.push(['ID', 'Brand', 'Reference', 'Dial', 'Price', 'USD', 'Currency', 'Condition', 'Year', 'Confidence', 'Status', 'Raw Message'].join(','));

  // Data rows ΓÇö EXACT same format as the Excel sheet
  watches.forEach((w, i) => {
    const missingCount = getMissingCount(w);
    const status = statusFromVerdict(w.verdict, missingCount);
    const price = w.parsed.price || 0;
    const usd = w.parsed.currency === 'HKD' && price > 0
      ? Math.round(price / 7.8)
      : price;

    rows.push([
      escapeCsv(`clean_${i}`),
      escapeCsv(w.parsed.brand),
      escapeCsv(w.parsed.reference || 'Unknown'),
      escapeCsv(w.parsed.dialColor || 'UNKNOWN'),
      escapeCsv(price),
      escapeCsv(usd),
      escapeCsv(w.parsed.currency || 'Unknown'),
      escapeCsv(w.parsed.condition),
      escapeCsv(w.parsed.year ?? ''),
      escapeCsv(w.confidence),
      escapeCsv(status),
      escapeCsv(w.input),
    ].join(','));
  });

  const csv = rows.join('\n');
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const link = document.createElement('a');
  const now = new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-');
  link.href = URL.createObjectURL(blob);
  link.download = `WatchFacts_CleanAnalysis_${now}.csv`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(link.href);
}

// Currency detection + normalization for watch chat messages
// Supports: USD, HKD, EUR, GBP, CHF, JPY, SGD, AUD, CAD

export interface CurrencyInfo {
  code: string;
  symbol: string;
  rateToUSD: number;
}

const CURRENCIES: CurrencyInfo[] = [
  { code: 'USD', symbol: '$', rateToUSD: 1.0 },
  { code: 'HKD', symbol: 'HK$', rateToUSD: 0.128 },
  { code: 'EUR', symbol: 'Γé¼', rateToUSD: 1.08 },
  { code: 'GBP', symbol: '┬ú', rateToUSD: 1.27 },
  { code: 'CHF', symbol: 'CHF', rateToUSD: 1.13 },
  { code: 'JPY', symbol: '┬Ñ', rateToUSD: 0.0066 },
  { code: 'SGD', symbol: 'S$', rateToUSD: 0.74 },
  { code: 'AUD', symbol: 'A$', rateToUSD: 0.65 },
  { code: 'CAD', symbol: 'C$', rateToUSD: 0.73 },
];

export function detectCurrency(rawMessage: string): { currency: string; originalAmount: number; usdAmount: number } | null {
  if (!rawMessage) return null;

  const text = rawMessage.replace(/,/g, '');
  const matches: { currency: string; amount: number; index: number }[] = [];

  // Pattern: symbol/abbreviation followed by number
  const symRegex = /(?:^|\s|\b)(HKD|HKS|HK\$|Γé¼|EUR|┬ú|GBP|CHF|┬Ñ|JPY|S\$|SGD|A\$|AUD|C\$|CAD|US\$|\$)\s*([0-9\.]+(?:\s*[kK])?)/gi;
  let m: RegExpExecArray | null;
  while ((m = symRegex.exec(text)) !== null) {
    const sym = m[1].toUpperCase();
    const amtStr = m[2].toLowerCase();
    const multiplier = amtStr.includes('k') ? 1000 : 1;
    const amount = parseFloat(amtStr.replace(/k/i, '')) * multiplier;
    if (!isNaN(amount) && amount > 0) {
      matches.push({ currency: normalizeSymbol(sym), amount, index: m.index });
    }
  }

  // Pattern: number followed by symbol/abbreviation
  const numRegex = /([0-9\.]+(?:\s*[kK])?)\s*(HKD|HKS|HK\$|Γé¼|EUR|┬ú|GBP|CHF|┬Ñ|JPY|S\$|SGD|A\$|AUD|C\$|CAD|US\$|\$)/gi;
  while ((m = numRegex.exec(text)) !== null) {
    const sym = m[2].toUpperCase();
    const amtStr = m[1].toLowerCase();
    const multiplier = amtStr.includes('k') ? 1000 : 1;
    const amount = parseFloat(amtStr.replace(/k/i, '')) * multiplier;
    if (!isNaN(amount) && amount > 0) {
      matches.push({ currency: normalizeSymbol(sym), amount, index: m.index });
    }
  }

  if (matches.length === 0) return null;

  // Prefer explicit non-USD if present (HK$500k vs $500k)
  const nonUsd = matches.find((x) => x.currency !== 'USD');
  const pick = nonUsd || matches[0];

  const info = CURRENCIES.find((c) => c.code === pick.currency);
  if (!info) return null;

  return {
    currency: pick.currency,
    originalAmount: Math.round(pick.amount),
    usdAmount: Math.round(pick.amount * info.rateToUSD),
  };
}

function normalizeSymbol(sym: string): string {
  const map: Record<string, string> = {
    'HK$': 'HKD', 'HKS': 'HKD', 'HKD': 'HKD',
    'Γé¼': 'EUR', 'EUR': 'EUR',
    '┬ú': 'GBP', 'GBP': 'GBP',
    'CHF': 'CHF',
    '┬Ñ': 'JPY', 'JPY': 'JPY',
    'S$': 'SGD', 'SGD': 'SGD',
    'A$': 'AUD', 'AUD': 'AUD',
    'C$': 'CAD', 'CAD': 'CAD',
    'US$': 'USD', '$': 'USD',
  };
  return map[sym] || 'USD';
}

export function formatCurrencyUSD(amount: number): string {
  if (amount === 0 || !amount) return 'ΓÇö';
  return `$${amount.toLocaleString()}`;
}

