// ΓöÇΓöÇ CSV export ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export function exportDatasetCsv(records: WatchRecord[]) {
  const esc = (v: any) => {
    if (v === null || v === undefined) return '';
    const s = String(v);
    return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
  };

  const COLS = ['ID','Brand','Reference','Dial','Price','USD','Currency','Condition','Year','Confidence','Status','Raw Message'];
  const rows: string[] = [COLS.join(',')];

  for (const r of records) {
    const v = getVerdict(r);
    rows.push([
      esc(r.id),
      esc(r.brand),
      esc(r.reference),
      esc(r.dialColor),
      esc(r.originalPrice || r.price || 0),
      esc(r.price || 0),
      esc(r.originalCurrency || 'USD'),
      esc(r.condition),
      esc(r.year ?? ''),
      esc(r.confidence),
      esc(v),
      esc(r.rawMessage?.slice(0, 200) || ''),
    ].join(','));
  }

  const csv = '\uFEFF' + rows.join('\r\n');   // BOM for Excel UTF-8
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const link = document.createElement('a');
  const stamp = new Date().toISOString().slice(0, 10);
  link.href = URL.createObjectURL(blob);
  link.download = `WatchFacts_Export_${records.length}records_${stamp}.csv`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(link.href);
}

/**
 * Client for /api/enrich ΓÇö structured watch enrichment.
 * Returns catalog data, market prices (chrono24/watchcharts), and official URLs.
 */

export interface EnrichmentData {
  reference: string | null;
  catalog: {
    model: string | null;
    collection: string | null;
    caseMetal: string | null;
    productionYears: string | null;
    status: string | null;
    liquidityScore: number | null;
    buyerRatio: number | null;
    sellerRatio: number | null;
  } | null;
  market: {
    chrono24: {
      source: string;
      url: string;
      listingCount: number | null;
      priceRange: { low: number; high: number; median: number } | null;
      imageUrl: string | null;
    } | null;
    watchcharts: {
      source: string;
      url: string | null;
      priceRange: { low: number; high: number } | null;
    } | null;
    ddgTopResult: {
      title: string;
      url: string;
      snippet: string;
    } | null;
  };
  officialUrl: string | null;
  confidenceBoost: number;
}

export interface EnrichResponse {
  success: boolean;
  enrichment: EnrichmentData | null;
  error?: string;
}

export async function enrichWatch(reference: string, brand?: string): Promise<EnrichResponse> {
  try {
    const params = new URLSearchParams();
    if (reference) params.set('reference', reference);
    if (brand) params.set('brand', brand);
    const res = await fetch(`/api/enrich?${params.toString()}`);
    const data = await res.json();
    if (!res.ok) {
      return { success: false, enrichment: null, error: data.error || `HTTP ${res.status}` };
    }
    return data;
  } catch (e: any) {
    return { success: false, enrichment: null, error: e.message };
  }
}

export interface ImageAnalysisResult {
  success: boolean;
  dialColor: string;
  confidence: number;
  brand: string | null;
  notes: string;
  raw?: string;
  error?: string;
}

export async function analyzeWatchImage(imageUrl: string, reference?: string): Promise<ImageAnalysisResult> {
  try {
    const res = await fetch('/api/analyze-image', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ imageUrl, reference }),
    });

    if (!res.ok) {
      const err = await res.json().catch(() => ({ error: 'Unknown error' }));
      return { success: false, dialColor: 'UNKNOWN', confidence: 0, brand: null, notes: '', error: err.error || `HTTP ${res.status}` };
    }

    return await res.json();
  } catch (e: any) {
    return { success: false, dialColor: 'UNKNOWN', confidence: 0, brand: null, notes: '', error: e.message };
  }
}

// Batch processor with rate limiting (1 req / 2 sec to avoid rate limits)
export async function batchAnalyzeImages(
  items: { id: string; imageUrl: string; reference?: string }[],
  onProgress?: (done: number, total: number, current: string) => void
): Promise<Record<string, ImageAnalysisResult>> {
  const results: Record<string, ImageAnalysisResult> = {};

  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    onProgress?.(i, items.length, item.id);

    try {
      const result = await analyzeWatchImage(item.imageUrl, item.reference);
      results[item.id] = result;
    } catch (e: any) {
      results[item.id] = { success: false, dialColor: 'UNKNOWN', confidence: 0, brand: null, notes: '', error: e.message };
    }

    // Rate limit: wait 2 seconds between calls
    if (i < items.length - 1) {
      await new Promise((r) => setTimeout(r, 2000));
    }
  }

  onProgress?.(items.length, items.length, 'done');
  return results;
}

