        'EUR': data.rates.EUR ? 1 / data.rates.EUR : 1.08,
        'GBP': data.rates.GBP ? 1 / data.rates.GBP : 1.27,
        'CHF': data.rates.CHF ? 1 / data.rates.CHF : 1.13,
        'JPY': data.rates.JPY ? 1 / data.rates.JPY : 0.0066,
