}

// ΓöÇΓöÇ IQR Outlier Removal ΓöÇΓöÇ

export interface OutlierResult {
  keep: number[];
  remove: number[];
  q1: number;
  q3: number;
  iqr: number;
  lowerBound: number;
  upperBound: number;
}

export function iqrOutlierRemoval(prices: number[]): OutlierResult {
  if (prices.length < 5) {
    return { keep: prices, remove: [], q1: 0, q3: 0, iqr: 0, lowerBound: 0, upperBound: 0 };
  }
  const sorted = [...prices].sort((a, b) => a - b);
  const q1Idx = Math.floor(sorted.length * 0.25);
  const q3Idx = Math.floor(sorted.length * 0.75);
  const q1 = sorted[q1Idx];
  const q3 = sorted[q3Idx];
  const iqr = q3 - q1;
  const lowerBound = q1 - 1.5 * iqr;
  const upperBound = q3 + 1.5 * iqr;

  return {
    keep: prices.filter(p => p >= lowerBound && p <= upperBound),
    remove: prices.filter(p => p < lowerBound || p > upperBound),
    q1,
    q3,
    iqr,
    lowerBound,
    upperBound,
  };
}

/** Group records by reference+dial and apply IQR filtering. */
export function applyIQRFiltering<T extends { reference: string; dialColor: string; price: number }>(
  records: T[],
  minDataPoints = 5
): { clean: T[]; outliers: T[]; insufficient: T[]; stats: Record<string, OutlierResult> } {
  const groups = new Map<string, T[]>();
  for (const r of records) {
    const key = `${r.reference}::${r.dialColor || 'UNKNOWN'}`;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key)!.push(r);
  }

  const clean: T[] = [];
  const outliers: T[] = [];
  const insufficient: T[] = [];
  const stats: Record<string, OutlierResult> = {};

  for (const [key, recs] of groups) {
    const prices = recs.map(r => r.price).filter(p => p > 0);
    if (prices.length < minDataPoints) {
      insufficient.push(...recs);
      continue;
    }
    const result = iqrOutlierRemoval(prices);
    stats[key] = result;
    const keepSet = new Set(result.keep);
    for (const r of recs) {
      if (r.price > 0 && keepSet.has(r.price)) clean.push(r);
      else outliers.push(r);
    }
  }

  return { clean, outliers, insufficient, stats };
}

/**
 * CLIENT-SIDE PIPELINE INTEGRATION
 * Hooks into the existing useWatchData flow to apply:
 * - Master catalog lookup
 * - Multi-stage normalization
 * - IQR outlier flagging
 * - Currency conversion
 */

import {
  runPipeline,
  applyIQRFiltering,
} from './pipeline';
import { lookupReference, getCatalogStats } from './masterCatalog';

export interface EnrichedWatchRecord {
  id: string;
  brand: string;
  reference: string;
  family: string;
  dialColor: string;
  condition: string;
  year: number | null;
  priceUSD: number;
  originalPrice: number;
  currency: string;
  hasBox: boolean;
  hasPapers: boolean;
  materials: string[];
  confidence: number;
  flags: string[];
  source: string;
  // IQR
  isOutlier: boolean;
  outlierReason?: string;
  // Catalog
  catalogVerified: boolean;
  catalogEntry?: {
    standardDials: string[];
    avgPriceUSD: number;
    count: number;
  };
  // Image verification
  imageVerdict?: 'MATCH' | 'MISMATCH' | 'UNVERIFIED';
  imageDiscrepancies?: string[];
}

/** Enrich raw records with full pipeline processing */
export async function enrichRecords(
  rawRecords: Array<{
    id: string;
    sourceLine: string;
    brand: string;
    reference: string;
    dialColor: string;
    condition: string;
    price: number;
    currency: string;
    priceUSD: number;
    year?: number | null;
    imageUrl?: string | null;
  }>
): Promise<EnrichedWatchRecord[]> {
  // Step 1: Run pipeline on each record
  const pipelineResults = await Promise.all(
    rawRecords.map(async (r) => {
      const normalized = await runPipeline(r.sourceLine || '');
      return { raw: r, normalized };
    })
  );

  // Step 2: Apply IQR filtering per reference+dial group
  const forIqr = pipelineResults.map((p) => ({
    reference: p.normalized.reference,
    dialColor: p.normalized.dialColor,
    price: p.normalized.priceUSD || 0,
    record: p,
  }));

  const { outliers } = applyIQRFiltering(forIqr, 5);
  const outlierSet = new Set(outliers.map((o) => o.record.raw.id));

  // Step 3: Build enriched records
  const enriched: EnrichedWatchRecord[] = [];
  for (const { raw, normalized } of pipelineResults) {
    const isOutlier = outlierSet.has(raw.id);

    // Catalog lookup
    let catalogEntry = null;
    try {
      const entry = await lookupReference(normalized.reference);
      if (entry) {
        const totalPrices = entry.standardDials.flatMap((d) =>
          Array(d.count).fill(d.avgPriceUSD)
        );
        catalogEntry = {
          standardDials: entry.standardDials.map((d) => d.color),
          avgPriceUSD: totalPrices.length > 0
            ? Math.round(totalPrices.reduce((a, b) => a + b, 0) / totalPrices.length)
            : 0,
          count: entry.standardDials.reduce((s, d) => s + d.count, 0),
        };
      }
    } catch { /* ignore */ }

    enriched.push({
      id: raw.id,
      brand: normalized.brand,
      reference: normalized.reference,
      family: normalized.family,
      dialColor: normalized.dialColor,
      condition: normalized.condition,
      year: normalized.year,
      priceUSD: normalized.priceUSD || raw.priceUSD || 0,
      originalPrice: normalized.originalPrice || raw.price || 0,
      currency: normalized.currency || raw.currency || 'USD',
      hasBox: normalized.hasBox,
      hasPapers: normalized.hasPapers,
      materials: normalized.materials,
      confidence: normalized.confidence,
      flags: [...normalized.flags, ...(isOutlier ? ['IQR_OUTLIER'] : [])],
      source: normalized.source,
      isOutlier,
      outlierReason: isOutlier ? 'Price is statistical outlier for this reference+dial' : undefined,
      catalogVerified: !!catalogEntry,
      catalogEntry: catalogEntry || undefined,
    });
  }

  return enriched;
}

/** Quick catalog stats for UI */
export async function getPipelineStats(): Promise<{
  catalogBrands: number;
  catalogReferences: number;
  catalogDialVariants: number;
}> {
  const stats = await getCatalogStats();
  return {
    catalogBrands: stats.brands,
    catalogReferences: stats.references,
