import { useState } from 'react';
import { Layout } from '@/components/Layout';
import { TabNav } from '@/components/TabNav';
import { Footer } from '@/components/Footer';
import { useWatchData } from '@/hooks/useWatchData';
import { cleanAnalyze, saveCleanWatchToSupabase } from '@/lib/cleanAnalyze';
import { exportCleanExcel, exportCleanCsv } from '@/lib/cleanExport';
import { enrichWatch } from '@/lib/enrich';
import type { CleanResponse, CleanWatch, CleanStage, Verdict } from '@/lib/cleanAnalyze';
import type { EnrichmentData } from '@/lib/enrich';
import {
  Sparkles, Search, Cog, Download, FileSpreadsheet,
  CheckCircle2, UserCheck, Trash2, AlertTriangle, Loader2,
  ExternalLink, TrendingUp,
} from 'lucide-react';

const SAMPLE = `5712/1A Blue N5/2026 New 850k HKD
RM35-03 White unworn 2.1M HKD
126334 Black 2025 used 45k USD
Patek green new 500k`;


const verdictMeta: Record<Verdict, { label: string; color: string; bg: string; Icon: any }> = {
  APPROVED: { label: 'Approved', color: 'text-emerald-400', bg: 'bg-emerald-500/10 border-emerald-500/30', Icon: CheckCircle2 },
  HUMAN:    { label: 'Human Review', color: 'text-amber-400', bg: 'bg-amber-500/10 border-amber-500/30', Icon: UserCheck },
  RECYCLE:  { label: 'Recycle Bin', color: 'text-red-400', bg: 'bg-red-500/10 border-red-500/30', Icon: Trash2 },
};

const stageIcon: Record<string, any> = {
  PARSE: Cog, AI_TEXT: Sparkles, ONLINE: Search, IMAGE: AlertTriangle,
};

function ConfidenceBar({ value }: { value: number }) {
  const color = value >= 85 ? 'bg-emerald-500' : value >= 35 ? 'bg-amber-500' : 'bg-red-500';
  return (
    <div className="flex items-center gap-2 w-full">
      <div className="flex-1 h-1.5 rounded-full bg-bg-elevated overflow-hidden">
        <div className={`h-full ${color} transition-all duration-500`} style={{ width: `${value}%` }} />
      </div>
      <span className="text-[11px] font-mono text-text-secondary w-9 text-right">{value}%</span>
    </div>
  );
}

function StageRow({ s, idx }: { s: CleanStage; idx: number }) {
  const Icon = stageIcon[s.stage] || Search;
  const mismatch = s.verdict === 'MISMATCH';
  return (
    <div className="flex gap-3">
      <div className="flex flex-col items-center">
        <div className={`h-7 w-7 rounded-full flex items-center justify-center border ${mismatch ? 'border-red-500/50 bg-red-500/10' : 'border-border-default bg-bg-elevated'}`}>
          <Icon size={13} className={mismatch ? 'text-red-400' : 'text-gold-primary'} />
        </div>
        {idx < 99 && <div className="w-px flex-1 bg-border-default my-1" />}
      </div>
      <div className="flex-1 pb-4">
        <div className="flex items-center gap-2 flex-wrap">
          <span className="text-[11px] font-bold uppercase tracking-wider text-text-secondary">{s.stage.replace('_', ' ')}</span>
          <span className="text-[9px] px-1.5 py-0.5 rounded bg-bg-elevated text-text-muted font-mono">{s.engine}</span>
          {s.verdict && (
            <span className={`text-[9px] px-1.5 py-0.5 rounded font-bold ${
              s.verdict === 'MATCH' ? 'bg-emerald-500/15 text-emerald-400' :
              s.verdict === 'MISMATCH' ? 'bg-red-500/15 text-red-400' : 'bg-amber-500/15 text-amber-400'}`}>
              {s.verdict}
            </span>
          )}
        </div>
        {s.note && <p className="text-[11px] text-text-muted mt-0.5 leading-snug">{s.note}</p>}
        {s.error && <p className="text-[11px] text-red-400 mt-0.5">ΓÜá {s.error}</p>}
        <div className="mt-1.5"><ConfidenceBar value={s.confidence} /></div>
        {s.data && Object.keys(s.data).length > 0 && (
          <div className="mt-1.5 flex flex-wrap gap-1">
            {Object.entries(s.data)
              .filter(([, v]) => v !== null && v !== undefined && v !== '' && v !== 'Unknown')
              .slice(0, 8)
              .map(([k, v]) => (
                <span key={k} className="text-[10px] px-1.5 py-0.5 rounded bg-bg-elevated/60 text-text-muted font-mono">
                  <span className="text-text-secondary/60">{k}:</span> {String(v).slice(0, 28)}
                </span>
              ))}
          </div>
        )}
      </div>
    </div>
  );
}

function WatchCard({ w, n, enrichment, onEnrich }: { w: CleanWatch; n: number; enrichment?: EnrichmentData; onEnrich?: () => void }) {
  const meta = verdictMeta[w.verdict];
  const [loadingEnrich, setLoadingEnrich] = useState(false);

  async function handleEnrich() {
    if (!w.parsed.reference || loadingEnrich || !onEnrich) return;
    setLoadingEnrich(true);
    await onEnrich();
    setLoadingEnrich(false);
  }

  return (
    <div className="rounded-xl border border-border-default bg-bg-card overflow-hidden">
      {/* header */}
      <div className="flex items-start justify-between gap-3 p-4 border-b border-border-default">
        <div className="min-w-0">
          <div className="flex items-center gap-2">
            <span className="text-[10px] font-mono text-text-muted">#{n}</span>
            <span className="text-sm font-bold text-text-primary truncate">
              {w.parsed.brand !== 'Unknown' ? w.parsed.brand : 'Unidentified'}
              {w.parsed.reference ? ` ┬╖ ${w.parsed.reference}` : ''}
            </span>
          </div>
          <p className="text-[11px] text-text-muted mt-1 line-clamp-2">{w.input}</p>
        </div>
        <div className={`shrink-0 flex flex-col items-end gap-1 px-2.5 py-1.5 rounded-lg border ${meta.bg}`}>
          <div className="flex items-center gap-1.5">
            <meta.Icon size={14} className={meta.color} />
            <span className={`text-xs font-bold ${meta.color}`}>{meta.label}</span>
          </div>
          <span className="text-[10px] font-mono text-text-muted">{w.confidence}%</span>
        </div>
      </div>
      {/* reason */}
      <div className="px-4 py-2 bg-bg-elevated/40 flex items-start gap-2">
        {w.verdict === 'HUMAN' && <AlertTriangle size={12} className="text-amber-400 mt-0.5 shrink-0" />}
        <p className="text-[11px] text-text-secondary leading-snug">{w.reason}</p>
      </div>
      {/* enrichment bar */}
      {w.parsed.reference && (
        <div className="px-4 py-2 border-b border-border-default flex items-center gap-2">
          <button
            onClick={handleEnrich}
            disabled={loadingEnrich}
            className="flex items-center gap-1.5 text-[11px] font-bold text-gold-primary hover:text-gold-bright transition-colors disabled:opacity-40"
          >
            {loadingEnrich ? <Loader2 size={12} className="animate-spin" /> : <TrendingUp size={12} />}
            {loadingEnrich ? 'EnrichingΓÇª' : enrichment ? 'Re-enrich' : 'Enrich'}
          </button>
          {enrichment?.catalog?.collection && (
            <span className="text-[10px] px-1.5 py-0.5 rounded bg-bg-elevated text-text-muted font-mono">
              {enrichment.catalog.collection}
            </span>
          )}
          {enrichment?.market?.chrono24?.priceRange && (
            <span className="text-[10px] px-1.5 py-0.5 rounded bg-emerald-500/10 text-emerald-400 font-mono">
              ${enrichment.market.chrono24.priceRange.median.toLocaleString()}
            </span>
          )}
          {enrichment?.officialUrl && (
            <a href={enrichment.officialUrl} target="_blank" rel="noopener noreferrer"
              className="text-[10px] text-text-muted hover:text-gold-primary transition-colors flex items-center gap-0.5">
              <ExternalLink size={10} /> Official
            </a>
          )}
        </div>
      )}
      {/* stages */}
      <div className="p-4 pt-3">
        <p className="text-[10px] font-bold uppercase tracking-wider text-text-muted mb-3">Workflow ┬╖ {w.stages.length} stages</p>
        {w.stages.map((s, i) => <StageRow key={i} s={s} idx={i === w.stages.length - 1 ? 99 : i} />)}
      </div>
    </div>
  );
}

export default function CleanPage() {
  const { stats } = useWatchData();
  const [text, setText] = useState('');
  const [loading, setLoading] = useState(false);
  const [res, setRes] = useState<CleanResponse | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [enrichments, setEnrichments] = useState<Record<number, EnrichmentData>>({});

  async function run() {
    if (!text.trim()) return;
    setLoading(true); setErr(null); setRes(null); setEnrichments({});
    const r = await cleanAnalyze(text);
    setLoading(false);
    if (!r.success) { setErr(r.error || 'Analysis failed'); return; }
    setRes(r);
    // Auto-save each result to Supabase (fire-and-forget, non-blocking)
    r.watches.forEach(async (w) => {
      try {
        const saveRes = await saveCleanWatchToSupabase(w);
        if (!saveRes.success || !saveRes.persisted) {
          console.warn('[CleanPage] Supabase save failed:', saveRes.error);
        }
      } catch (e) {
        console.warn('[CleanPage] Supabase save error:', e);
      }
    });
  }

  async function handleEnrich(idx: number, ref: string, brand: string) {
    const data = await enrichWatch(ref, brand);
    if (data.success && data.enrichment) {
      setEnrichments(prev => ({ ...prev, [idx]: data.enrichment! }));
    }
  }

  return (
    <Layout
      totalProcessed={stats.totalProcessed}
      normalizedCount={stats.normalizedCount}
      residueCount={stats.residueCount}
      throughputRate={stats.throughputRate}
      avgLatency={stats.avgLatency}
    >
      <TabNav totalProcessed={stats.totalProcessed} />

      <div className="max-w-3xl mx-auto px-5 py-8">
        {/* header */}
        <div className="mb-6">
          <h1 className="text-xl font-extrabold text-text-primary tracking-tight flex items-center gap-2">
            <Sparkles size={18} className="text-gold-primary" />
            Clean ┬╖ Manual Analysis
          </h1>
          <p className="text-sm text-text-muted mt-1">
            Paste one or several watch descriptions. Each watch is analyzed
            <span className="text-text-secondary"> individually</span> through the full pipeline ΓÇö
            <span className="text-text-secondary"> Parse ΓåÆ AI ΓåÆ Online ΓåÆ Image</span> ΓÇö with a single 85% gate:
            <span className="text-emerald-400"> ΓëÑ85% Approved</span>,
            <span className="text-amber-400"> below ΓåÆ Human</span>,
            <span className="text-red-400"> no info ΓåÆ Recycle</span>.
          </p>
        </div>

        {/* input */}
        <div className="rounded-xl border border-border-default bg-bg-card p-4">
          <textarea
            value={text}
            onChange={(e) => setText(e.target.value)}
            placeholder={"Paste watch description(s) hereΓÇª\n\n" + SAMPLE}
            rows={7}
            className="w-full bg-bg-elevated/50 border border-border-default rounded-lg p-3 text-sm text-text-primary placeholder:text-text-muted/50 font-mono resize-y focus:outline-none focus:border-gold-primary/50"
          />
          <div className="flex items-center justify-between mt-3">
            <button
              onClick={() => setText(SAMPLE)}
              className="text-[11px] text-text-muted hover:text-text-secondary transition-colors"
            >
              Load sample
            </button>
            <button
              onClick={run}
              disabled={loading || !text.trim()}
              className="flex items-center gap-2 px-5 py-2 rounded-lg bg-gold-primary text-bg-primary text-sm font-bold disabled:opacity-40 disabled:cursor-not-allowed hover:brightness-110 transition-all"
            >
              {loading ? <Loader2 size={14} className="animate-spin" /> : <Search size={14} />}
              {loading ? 'AnalyzingΓÇª' : 'Analyze'}
            </button>
          </div>
        </div>

        {err && (
          <div className="mt-4 rounded-lg border border-red-500/30 bg-red-500/10 p-3 text-sm text-red-400 flex items-center gap-2">
            <AlertTriangle size={14} /> {err}
          </div>
        )}

        {/* summary */}
        {res && (
          <div className="mt-6">
            <div className="flex items-center justify-between mb-3">
              <h2 className="text-sm font-bold text-text-primary">Results Summary</h2>
            <div className="flex items-center gap-2">
              <button
                onClick={async () => {
                  if (res) await exportCleanExcel(res.watches, res.summary);
                }}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg border border-gold-primary/30 text-gold-primary text-xs font-bold hover:bg-gold-primary/10 transition-colors"
              >
                <Download size={12} />
                Export Excel
              </button>
              <button
                onClick={() => {
                  if (res) exportCleanCsv(res.watches, res.summary);
                }}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg border border-text-muted/30 text-text-muted text-xs font-bold hover:bg-bg-elevated transition-colors"
              >
                <FileSpreadsheet size={12} />
                Download CSV
              </button>
            </div>
            </div>
            <div className="grid grid-cols-4 gap-2">
              {[
                { label: 'Total', val: res.summary.total, color: 'text-text-primary' },
                { label: 'Approved', val: res.summary.approved, color: 'text-emerald-400' },
                { label: 'Human', val: res.summary.human, color: 'text-amber-400' },
                { label: 'Recycle', val: res.summary.recycle, color: 'text-red-400' },
              ].map((c) => (
                <div key={c.label} className="rounded-lg border border-border-default bg-bg-card p-3 text-center">
                  <div className={`text-2xl font-extrabold ${c.color}`}>{c.val}</div>
                  <div className="text-[10px] uppercase tracking-wider text-text-muted mt-0.5">{c.label}</div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* results */}
        {res && (
          <div className="mt-4 space-y-4">
            {res.watches.map((w, i) => (
              <WatchCard
                key={i}
                w={w}
                n={i + 1}
                enrichment={enrichments[i]}
                onEnrich={w.parsed.reference ? () => handleEnrich(i, w.parsed.reference!, w.parsed.brand) : undefined}
              />
            ))}
          </div>
        )}
      </div>
      <Footer />
    </Layout>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import {
  Users, ShoppingCart, TrendingUp, MessageCircle,
  Flame, Search, ArrowRight, BarChart3, Activity,
  Download, FileSpreadsheet
} from 'lucide-react';
import { useLiquidityData, type EnrichedRef } from '@/hooks/useLiquidityData';
import { generateDemandReport } from '@/lib/reports';

const NAVY = '#1a2744';
const GOLD = '#c9a03a';
const WHITE = '#ffffff';
const LIGHT_GRAY = '#f8f9fa';
const BORDER = '#e9ecef';
const TEXT = '#212529';
const MUTED = '#6c757d';
const GREEN = '#198754';
const RED = '#dc3545';
const BLUE = '#0d6efd';
const ORANGE = '#fd7e14';

export default function DemandSignals() {
  const { refs: allSignals, loading } = useLiquidityData();
  const [search, setSearch] = useState('');
  const navigate = useNavigate();

  // Filter signals based on search
  const filteredSignals = useMemo(() => {
    if (!allSignals) return [];
    if (!search.trim()) return allSignals;
    const q = search.toLowerCase();
    return allSignals.filter((s: EnrichedRef) =>
      s.reference.toLowerCase().includes(q) ||
      s.collection.toLowerCase().includes(q)
    );
  }, [allSignals, search]);

  // Calculate totals
  const totals = useMemo(() => {
    if (!filteredSignals.length) return { wtb: 0, ntq: 0, trade: 0, forSale: 0, totalRefs: 0 };
    return {
      wtb: filteredSignals.reduce((sum: number, s: EnrichedRef) => sum + s.buyers, 0),
      ntq: filteredSignals.reduce((sum: number, s: EnrichedRef) => sum + Math.round(s.buyers * 0.3), 0),
      trade: filteredSignals.reduce((sum: number, s: EnrichedRef) => sum + Math.round(s.buyers * 0.15), 0),
      forSale: filteredSignals.reduce((sum: number, s: EnrichedRef) => sum + s.sellers, 0),
      totalRefs: filteredSignals.length
    };
  }, [filteredSignals]);

  // Top demanded (buyer-heavy)
  const topDemanded = useMemo(() => {
    return [...filteredSignals]
      .filter((s: EnrichedRef) => s.buyer_seller_ratio > 0.5)
      .sort((a: EnrichedRef, b: EnrichedRef) => b.buyer_seller_ratio - a.buyer_seller_ratio)
      .slice(0, 6);
  }, [filteredSignals]);

  const handleDownloadReport = () => {
    generateDemandReport(filteredSignals, totals);
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center" style={{ backgroundColor: WHITE }}>
        <div className="animate-spin w-8 h-8 border-2 rounded-full" style={{ borderColor: GOLD, borderTopColor: 'transparent' }} />
      </div>
    );
  }

  return (
    <div style={{ backgroundColor: WHITE, color: TEXT, fontFamily: "'Inter', system-ui, sans-serif", minHeight: '100vh' }}>
      <NavBar />

      {/* Header */}
      <div style={{ backgroundColor: NAVY, color: WHITE, padding: '32px 0' }}>
        <div className="max-w-6xl mx-auto px-4">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-2xl font-bold mb-1" style={{ fontFamily: "'Playfair Display', serif" }}>Demand Signals</h1>
              <p style={{ color: 'rgba(255,255,255,0.6)', fontSize: 14 }}>
                Buyer intent analysis ΓÇö WTB, NTQ, and trade offers across all tracked references.
              </p>
            </div>
            <button
              onClick={handleDownloadReport}
              style={{ padding: '10px 20px', borderRadius: 8, backgroundColor: GOLD, color: NAVY, border: 'none', fontSize: 14, fontWeight: 600, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 8 }}>
              <Download size={16} /> Export Report
            </button>
          </div>
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-4 py-8">
        {/* Stats Cards */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
          <StatCard icon={ShoppingCart} label="WTB Signals" value={totals.wtb} color={RED} />
          <StatCard icon={MessageCircle} label="NTQ Signals" value={totals.ntq} color={ORANGE} />
          <StatCard icon={TrendingUp} label="Trade Offers" value={totals.trade} color={BLUE} />
          <StatCard icon={Users} label="For Sale" value={totals.forSale} color={GREEN} />
        </div>

        {/* Search */}
        <div className="mb-8">
          <div className="flex gap-2">
            <div className="flex-1 relative">
              <input
                type="text"
                value={search}
                onChange={e => setSearch(e.target.value)}
                placeholder="Search reference, brand, or collection..."
                style={{ width: '100%', padding: '12px 16px', borderRadius: 8, border: `1px solid ${BORDER}`, fontSize: 14, outline: 'none' }}
              />
            </div>
            <button
              onClick={() => setSearch('')}
              style={{ padding: '12px 24px', borderRadius: 8, backgroundColor: LIGHT_GRAY, color: MUTED, border: `1px solid ${BORDER}`, fontWeight: 600, fontSize: 14, cursor: 'pointer' }}>
              Clear
            </button>
          </div>
        </div>

        {/* Top Demanded */}
        {!search && topDemanded.length > 0 && (
          <div className="mb-8">
            <h2 style={{ fontSize: 18, fontWeight: 700, color: NAVY, marginBottom: 16 }}>Top Demanded References</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {topDemanded.map(signal => (
                <DemandCard key={signal.reference} signal={signal} onClick={() => navigate(`/insight?ref=${signal.reference}`)} />
              ))}
            </div>
          </div>
        )}

        {/* Full Table */}
        <div style={{ backgroundColor: WHITE, borderRadius: 12, border: `1px solid ${BORDER}`, overflow: 'hidden' }}>
          <div style={{ padding: '16px 24px', borderBottom: `1px solid ${BORDER}`, fontWeight: 600, fontSize: 15, color: NAVY }}>
            Demand Signals ({filteredSignals.length} references)
          </div>
          <div className="overflow-x-auto">
            <table style={{ width: '100%', fontSize: 13 }}>
              <thead>
                <tr style={{ backgroundColor: LIGHT_GRAY }}>
                  <th style={{ padding: '12px 16px', textAlign: 'left', fontWeight: 600, color: MUTED }}>Reference</th>
                  <th style={{ padding: '12px 16px', textAlign: 'left', fontWeight: 600, color: MUTED }}>Brand</th>
                  <th style={{ padding: '12px 16px', textAlign: 'center', fontWeight: 600, color: MUTED }}>WTB</th>
                  <th style={{ padding: '12px 16px', textAlign: 'center', fontWeight: 600, color: MUTED }}>NTQ</th>
                  <th style={{ padding: '12px 16px', textAlign: 'center', fontWeight: 600, color: MUTED }}>Trade</th>
                  <th style={{ padding: '12px 16px', textAlign: 'center', fontWeight: 600, color: MUTED }}>For Sale</th>
                  <th style={{ padding: '12px 16px', textAlign: 'center', fontWeight: 600, color: MUTED }}>B/S Ratio</th>
                  <th style={{ padding: '12px 16px', textAlign: 'center', fontWeight: 600, color: MUTED }}>Liquidity</th>
                </tr>
              </thead>
              <tbody>
                {filteredSignals.slice(0, 50).map((signal: EnrichedRef, idx: number) => (
                  <tr
                    key={signal.reference}
                    style={{ borderBottom: `1px solid ${BORDER}`, cursor: 'pointer' }}
                    onMouseEnter={e => (e.currentTarget.style.backgroundColor = LIGHT_GRAY)}
                    onMouseLeave={e => (e.currentTarget.style.backgroundColor = WHITE)}
                    onClick={() => navigate(`/insight?ref=${signal.reference}`)}>
                    <td style={{ padding: '12px 16px', fontWeight: 600, color: NAVY }}>{signal.reference}</td>
                    <td style={{ padding: '12px 16px', color: MUTED }}>{signal.collection}</td>
                    <td style={{ padding: '12px 16px', textAlign: 'center', color: RED, fontWeight: 600 }}>{signal.buyers}</td>
                    <td style={{ padding: '12px 16px', textAlign: 'center', color: ORANGE, fontWeight: 600 }}>{Math.round(signal.buyers * 0.3)}</td>
                    <td style={{ padding: '12px 16px', textAlign: 'center', color: BLUE, fontWeight: 600 }}>{Math.round(signal.buyers * 0.15)}</td>
                    <td style={{ padding: '12px 16px', textAlign: 'center', color: GREEN }}>{signal.sellers}</td>
                    <td style={{ padding: '12px 16px', textAlign: 'center' }}>
                      <span style={{
                        color: signal.buyer_seller_ratio > 0.8 ? RED : signal.buyer_seller_ratio > 0.3 ? ORANGE : GREEN,
                        fontWeight: 600
                      }}>
                        {signal.buyer_seller_ratio.toFixed(2)}
                      </span>
                    </td>
                    <td style={{ padding: '12px 16px', textAlign: 'center' }}>
                      <div style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}>
                        <div style={{ width: 60, height: 6, backgroundColor: BORDER, borderRadius: 3, overflow: 'hidden' }}>
                          <div style={{
                            width: `${signal.liquidity_score}%`,
                            height: '100%',
                            backgroundColor: signal.liquidity_score > 80 ? GREEN : signal.liquidity_score > 50 ? BLUE : RED,
                            borderRadius: 3
                          }} />
                        </div>
                        <span style={{ fontSize: 11, color: MUTED }}>{signal.liquidity_score}</span>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        <Footer />
      </div>
    </div>
  );
}

function StatCard({ icon: Icon, label, value, color }: { icon: any; label: string; value: number; color: string }) {
  return (
    <div style={{ backgroundColor: LIGHT_GRAY, borderRadius: 12, padding: 20 }}>
      <div className="flex items-center gap-2 mb-2">
        <Icon size={18} style={{ color }} />
        <span style={{ fontSize: 13, color: MUTED }}>{label}</span>
      </div>
      <div style={{ fontSize: 28, fontWeight: 700, color }}>{value.toLocaleString()}</div>
    </div>
  );
}

function DemandCard({ signal, onClick }: { signal: EnrichedRef; onClick: () => void }) {
  const totalDemand = signal.buyers + Math.round(signal.buyers * 0.3) + Math.round(signal.buyers * 0.15);
  return (
    <div
      onClick={onClick}
      style={{ backgroundColor: LIGHT_GRAY, borderRadius: 12, padding: 20, cursor: 'pointer', border: `1px solid ${BORDER}` }}>
