        {signal.buyers > signal.sellers && (
          <span style={{ padding: '4px 10px', borderRadius: 20, backgroundColor: '#fef2f2', color: RED, fontSize: 11, fontWeight: 600 }}>
            <Flame size={12} style={{ display: 'inline', marginRight: 4 }} />HOT
