export default function DemoPage() {
  const [message, setMessage]     = useState('');
  const [loading, setLoading]     = useState(false);
  const [response, setResponse]   = useState<IngestResponse | null>(null);
  const [error, setError]         = useState<string | null>(null);

  async function handleAnalyze() {
    const text = message.trim();
    if (!text) return;
    setLoading(true);
    setError(null);
    setResponse(null);
    try {
      const res = await fetch('/api/ingest', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ rawMessage: text, source: 'demo' }),
      });
      const data: IngestResponse = await res.json();
      if (!res.ok || data.error) {
        setError(data.error ?? `HTTP ${res.status}`);
      } else {
        setResponse(data);
      }
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Network error');
    } finally {
      setLoading(false);
    }
  }

  function handleClear() {
    setMessage('');
    setResponse(null);
    setError(null);
  }

  function handleUpdateResult(idx: number, updated: Partial<ParseResult>) {
    if (!response) return;
    const newResults = [...response.results];
    newResults[idx] = { ...newResults[idx], ...updated };
    setResponse({ ...response, results: newResults });
  }

  return (
    <Layout>
      <TabNav />

      <div className="min-h-screen bg-gray-900 text-white px-4 py-8 max-w-2xl mx-auto">

        {/* Header */}
        <div className="flex items-center gap-3 mb-6">
          <div className="w-10 h-10 rounded-xl bg-yellow-500/20 border border-yellow-500/40 flex items-center justify-center">
            <FlaskConical size={20} className="text-yellow-400" />
          </div>
          <div>
            <h1 className="text-xl font-extrabold tracking-tight">Pipeline Demo</h1>
            <p className="text-xs text-gray-500">Paste a WhatsApp dealer message and run the full parse pipeline</p>
          </div>
        </div>

        {/* Example chips */}
        <div className="mb-4">
          <p className="text-[10px] uppercase tracking-widest text-gray-500 mb-2">Quick examples</p>
          <div className="flex flex-wrap gap-2">
            {EXAMPLES.map((ex) => (
              <button
                key={ex}
                onClick={() => setMessage(ex)}
                className="text-[11px] bg-gray-800 border border-gray-700 hover:border-yellow-500/60 hover:text-yellow-300 text-gray-400 rounded-full px-3 py-1 transition-colors truncate max-w-[260px]"
                title={ex}
              >
                {ex.length > 40 ? ex.slice(0, 38) + 'ΓÇª' : ex}
              </button>
            ))}
          </div>
        </div>

        {/* Textarea */}
        <textarea
          value={message}
          onChange={e => setMessage(e.target.value)}
          placeholder="Paste WhatsApp message here..."
          rows={5}
          className="w-full bg-gray-800 border border-gray-700 rounded-xl p-4 text-sm text-white placeholder-gray-600 resize-y focus:outline-none focus:border-yellow-500/60 transition-colors font-mono leading-relaxed mb-4"
        />

        {/* Action buttons */}
        <div className="flex gap-3 mb-6">
          <button
            onClick={handleAnalyze}
            disabled={loading || !message.trim()}
            className="flex items-center gap-2 px-5 py-2.5 bg-yellow-500 hover:bg-yellow-400 disabled:bg-gray-700 disabled:text-gray-500 text-gray-900 font-bold text-sm rounded-xl transition-colors"
          >
            {loading ? (
              <Loader2 size={15} className="animate-spin" />
            ) : (
              <Zap size={15} />
            )}
            {loading ? 'AnalyzingΓÇª' : 'Analyze'}
          </button>
          <button
            onClick={handleClear}
            className="flex items-center gap-2 px-4 py-2.5 bg-gray-800 hover:bg-gray-700 border border-gray-700 text-gray-400 hover:text-white font-semibold text-sm rounded-xl transition-colors"
          >
            <Trash2 size={14} />
            Clear
          </button>
        </div>

        {/* Error */}
        {error && (
          <div className="bg-red-500/10 border border-red-500/30 rounded-xl p-4 mb-4 text-sm text-red-400">
            Γ¥î {error}
          </div>
        )}

        {/* Bundle hint */}
        {response?.split && (
          <div className="bg-blue-500/10 border border-blue-500/30 rounded-xl p-3 mb-4 text-xs text-blue-300 flex items-center gap-2">
            <Zap size={14} />
            Multi-watch bundle detected ΓÇö {response.listingsFound} listings extracted
          </div>
        )}

        {/* Results */}
        {response && (
          <div>
            {/* Summary banner */}
            <div className="bg-gray-800 border border-gray-700 rounded-xl p-4 mb-4 flex items-center justify-between">
              <div className="text-sm">
                <span className="font-bold text-white">{response.listingsFound}</span>
                <span className="text-gray-400"> listing{response.listingsFound !== 1 ? 's' : ''} found</span>
                {response.split && (
                  <span className="ml-2 text-xs bg-blue-500/20 text-blue-400 px-2 py-0.5 rounded-full border border-blue-500/30">
                    multi-message split
                  </span>
                )}
              </div>
              <span className={`text-xs px-2 py-1 rounded border ${
                response.source === 'llm'
                  ? 'bg-purple-500/20 text-purple-400 border-purple-500/30'
                  : 'bg-blue-500/20 text-blue-400 border-blue-500/30'
              }`}>
                {response.source === 'llm' ? '≡ƒñû LLM assisted' : 'ΓÜí Regex engine'}
              </span>
            </div>

            {/* Per-listing pipeline stages */}
            {response.results.map((result, i) => (
              <PipelineResult key={result.index} result={result} index={i} onUpdateResult={handleUpdateResult} rawMessage={message} />
            ))}

            {/* Raw JSON viewer */}
            <JsonViewer data={response} />
          </div>
        )}
      </div>
    </Layout>
  );
}

import { useState, useCallback, useMemo } from 'react';
import { motion } from 'framer-motion';
import { Layout } from '@/components/Layout';
import { StatsBar } from '@/components/StatsBar';
import { Footer } from '@/components/Footer';
import { ProcessingTheater } from '@/sections/ProcessingTheater';
import { InventoryGrid } from '@/sections/InventoryGrid';
import { LiquidityTaxonomy } from '@/sections/LiquidityTaxonomy';
import { EnhancedResidue } from '@/sections/EnhancedResidue';
import { WorkflowSidebar } from '@/components/WorkflowSidebar';
import { TabNav } from '@/components/TabNav';
import { FloatingNav } from '@/components/FloatingNav';
import { DetailModal } from '@/components/DetailModal';
import { EditModal } from '@/components/EditModal';
import { AIInsights } from '@/sections/AIInsights';
import LiveStream from '@/components/LiveStream';
import { useWatchData } from '@/hooks/useWatchData';
import { exportDatasetExcel, exportDatasetCsv } from '@/lib/datasetExport';
import { downloadStyledReport } from '@/lib/reportGenerator';
import type { WatchRecord } from '@/types';

/** Derive verdict from confidence + flags (same as backend) */
function getVerdict(r: WatchRecord): 'APPROVED' | 'HUMAN' | 'RECYCLE' {
  if (r.isResidue || r.confidence < 35) return 'RECYCLE';
  if (r.confidence >= 90 && !r.failureFlags?.length) return 'APPROVED';
  return 'HUMAN';
}

export default function Home() {
  const { records, stats, loading, loadProgress, setRecords } = useWatchData();
  
  // Public pages only show APPROVED records (HUMAN/RECYCLE hidden)
  const publicRecords = useMemo(() => records.filter(r => getVerdict(r) === 'APPROVED'), [records]);

  // Modal state
  const [selectedRecord, setSelectedRecord] = useState<WatchRecord | null>(null);
  const [detailModalOpen, setDetailModalOpen] = useState(false);
  const [editModalOpen, setEditModalOpen] = useState(false);
  const [editingRecord, setEditingRecord] = useState<WatchRecord | null>(null);
  // Track which residue records have been reviewed (for authentic workflow)
  const [reviewedRecords, setReviewedRecords] = useState<Set<string>>(new Set());
  const [approvedRecords, setApprovedRecords] = useState<Set<string>>(new Set());
  const [deletedRecords, setDeletedRecords] = useState<Set<string>>(new Set());

  // ---- Handlers ----

  const handleSelectRecord = useCallback((record: WatchRecord) => {
    setSelectedRecord(record);
    setDetailModalOpen(true);
  }, []);

  const handleCloseDetail = useCallback(() => {
    setDetailModalOpen(false);
    setSelectedRecord(null);
  }, []);

  const handleOpenEdit = useCallback((record: WatchRecord) => {
    setEditingRecord(record);
    setEditModalOpen(true);
    setDetailModalOpen(false);
    setSelectedRecord(null);
  }, []);

  const handleCloseEdit = useCallback(() => {
    setEditModalOpen(false);
    setEditingRecord(null);
  }, []);

  const handleApprove = useCallback(async (record: WatchRecord) => {
    setApprovedRecords((prev) => new Set(prev).add(record.id));
    setReviewedRecords((prev) => new Set(prev).add(record.id));
    setDetailModalOpen(false);
    setSelectedRecord(null);
    try {
      await fetch('/api/update-record', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: record.id, verdict: 'APPROVED' })
      });
      setRecords((prev: WatchRecord[]) => prev.map(r => r.id === record.id ? { ...r, severity: 'INFO', isResidue: false } : r));
    } catch (err) {
      console.error('Failed to save approval to database:', err);
    }
  }, [setRecords]);

  const handleDelete = useCallback(async (record: WatchRecord) => {
    setDeletedRecords((prev) => new Set(prev).add(record.id));
    setReviewedRecords((prev) => new Set(prev).add(record.id));
    setDetailModalOpen(false);
    setSelectedRecord(null);
    try {
      await fetch('/api/update-record', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: record.id, verdict: 'RECYCLE' })
      });
      setRecords((prev: WatchRecord[]) => prev.map(r => r.id === record.id ? { ...r, severity: 'CRITICAL', isResidue: true } : r));
    } catch (err) {
      console.error('Failed to save delete/recycle to database:', err);
    }
  }, [setRecords]);

  const handleFlag = useCallback((record: WatchRecord) => {
    setReviewedRecords((prev) => new Set(prev).add(record.id));
    setDetailModalOpen(false);
    setSelectedRecord(null);
  }, []);

  const handleSaveEdit = useCallback(async (record: WatchRecord) => {
    setEditModalOpen(false);
    setEditingRecord(null);
    // Re-run AI parse on the updated record to get fresh confidence
    try {
      const res = await fetch('/api/ai-parse', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          rawMessage: record.rawMessage,
          currentGuess: {
            reference: record.reference,
            dialColor: record.dialColor,
            brand: record.brand,
            price: record.price,
            currency: record.originalCurrency,
          },
        }),
      });
      const resData = await res.json();
      if (resData.success) {
        const ai = Array.isArray(resData.parsed) ? resData.parsed[0] : resData.parsed;
        if (ai) {
          // Merge AI insights back into the record
          const updated: WatchRecord = {
            ...record,
            brand: ai.brand || record.brand,
            reference: ai.reference || record.reference,
            dialColor: ai.dialColor || record.dialColor,
            condition: ai.condition || record.condition,
            year: ai.year ?? record.year,
            price: ai.price || record.price,
            originalCurrency: ai.currency || record.originalCurrency,
            confidence: ai.confidence?.[0] && ai.confidence[0] >= 50
              ? Math.round(ai.confidence[0])
              : Math.min(100, record.confidence + 25), // Boost by 25 for human-verified
          };
          // Route to correct pipeline: ΓëÑ90 auto-approve, 60-89 AI review, <60 human
          updated.isResidue = updated.confidence < 60;
          const newVerdict = updated.confidence >= 90 ? 'APPROVED' : (updated.confidence >= 60 ? 'REVIEW' : 'HUMAN');

          // Persist changes to Supabase!
          await fetch('/api/update-record', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              id: record.id,
              verdict: newVerdict,
              brand: updated.brand,
              reference: updated.reference,
              dial_color: updated.dialColor,
              condition: updated.condition,
              year: updated.year,
              price_raw: updated.originalPrice,
              price_usd: updated.price,
              currency: updated.originalCurrency,
              confidence: updated.confidence
            })
          });

          // Update local state
          setRecords((prev: WatchRecord[]) => prev.map(r => r.id === record.id ? updated : r));
          
          console.log('[Save] Record', record.id, 're-parsed & saved to database, confidence:', updated.confidence,
            updated.isResidue ? 'ΓåÆ Residue' : updated.confidence >= 90 ? 'ΓåÆ Auto-Approved' : 'ΓåÆ AI Review');
        }
      }
    } catch (e) {
      console.error('[Save] AI re-parse failed:', e);
      // Fallback: approve record as-is
      const updated: WatchRecord = {
        ...record,
        confidence: Math.min(100, record.confidence + 15),
        isResidue: false,
      };
      try {
        await fetch('/api/update-record', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            id: record.id,
            verdict: 'APPROVED',
            brand: updated.brand,
            reference: updated.reference,
            dial_color: updated.dialColor,
            condition: updated.condition,
            year: updated.year,
            price_raw: updated.originalPrice,
            price_usd: updated.price,
            currency: updated.originalCurrency,
            confidence: updated.confidence
          })
        });
        setRecords((prev: WatchRecord[]) => prev.map(r => r.id === record.id ? updated : r));
      } catch (err) {
        console.error('Failed to save fallback edit to database:', err);
      }
    }
  }, [setRecords]);

  const handleExportExcel = useCallback(async () => {
    if (!records || records.length === 0) return;
    try {
      await exportDatasetExcel(records);
    } catch (e) {
      console.error('Excel export failed:', e);
      alert('Export failed: ' + (e as Error).message);
    }
  }, [records]);

  const handleExportCsv = useCallback(() => {
    if (!records || records.length === 0) return;
    exportDatasetCsv(records);
  }, [records]);

  const handleExportReport = useCallback(() => {
    if (!records || records.length === 0) return;
    downloadStyledReport(records.map(r => ({
      reference: r.reference,
      brand: r.brand,
      dialColor: r.dialColor,
      price: r.price,
      currency: r.originalCurrency,
      condition: r.condition,
      year: r.year,
      confidence: r.confidence,
      status: r.isResidue ? 'HUMAN_REVIEW' : r.confidence >= 90 ? 'AUTO_APPROVED' : 'AI_REVIEW',
      intent: (r as any).intent || 'SELL',
      rawMessage: r.rawMessage,
    })));
  }, [records]);

  if (loading) {
    return (
      <Layout
        totalProcessed={stats.totalProcessed}
        normalizedCount={stats.normalizedCount}
        residueCount={stats.residueCount}
        throughputRate={stats.throughputRate}
        avgLatency={stats.avgLatency}
      >
        <TabNav totalProcessed={stats.totalProcessed} />
        <div className="flex flex-col items-center justify-center py-32 gap-6">
          {/* Animated progress bar */}
          <div className="w-64 h-1.5 bg-bg-elevated rounded-full overflow-hidden">
            <motion.div
              className="h-full bg-gold-primary rounded-full"
              initial={{ width: '0%' }}
              animate={{ width: `${loadProgress}%` }}
              transition={{ duration: 0.3, ease: 'easeOut' }}
            />
          </div>
          <div className="h-10 w-10 rounded-full border-2 border-gold-primary/30 border-t-gold-primary animate-spin" />
          <p className="text-sm text-text-muted tracking-wide">
            Loading {stats.totalProcessed.toLocaleString()} recordsΓÇª {Math.round(loadProgress)}%
          </p>
          <p className="text-xs text-text-muted/50">
            Cache warming ΓÇö first load downloads ~20MB, subsequent tabs are instant
          </p>
        </div>
      </Layout>
    );
  }

  return (
    <Layout
      totalProcessed={stats.totalProcessed}
      normalizedCount={stats.normalizedCount}
      residueCount={stats.residueCount}
      throughputRate={stats.throughputRate}
      avgLatency={stats.avgLatency}
    >
      {/* Tab Navigation */}
      <TabNav totalProcessed={stats.totalProcessed} />

      {/* Workflow Sidebar */}
      <WorkflowSidebar
        totalRecords={stats.totalProcessed}
        normalizedCount={stats.normalizedCount}
        residueCount={stats.residueCount}
        onExportExcel={handleExportExcel}
        onExportCsv={handleExportCsv}
        onExportReport={handleExportReport}
      />

      <div className="ml-0">
        {/* Stats Bar */}
        <StatsBar
        totalProcessed={stats.totalProcessed}
        autoApproveRate={stats.accuracyRate}
        mlAvgTime={stats.mlAvgTime}
        residueRate={stats.residueRate}
      />

      {/* Processing Theater Section */}
      <ProcessingTheater
        records={publicRecords}
        normalizedCount={stats.normalizedCount}
        residueCount={stats.residueCount}
      />

      {/* Live Stream from Supabase ΓÇö real WhatsApp/Telegram messages */}
      <LiveStream />

      {/* Inventory Section */}
      <InventoryGrid
        records={publicRecords}
        onSelectRecord={handleSelectRecord}
      />

      {/* Liquidity & Taxonomy ΓÇö NEW */}
      <LiquidityTaxonomy />

      {/* AI Intelligence Center */}
      <AIInsights
        records={publicRecords}
        onSelectRecord={handleSelectRecord}
      />

      {/* Enhanced Residue Bin ΓÇö NEW */}
      <EnhancedResidue
        records={publicRecords}
        onApprove={handleApprove}
        onEdit={handleOpenEdit}
        onDelete={handleDelete}
        approvedRecords={approvedRecords}
        deletedRecords={deletedRecords}
        reviewedRecords={reviewedRecords}
      />

      </div>

      {/* Floating Navigation */}
      <FloatingNav />

      {/* Detail Modal */}
      <DetailModal
        record={selectedRecord}
        open={detailModalOpen}
        onClose={handleCloseDetail}
        onApprove={handleApprove}
        onEdit={handleOpenEdit}
        onFlag={handleFlag}
        onDelete={handleDelete}
      />

      {/* Edit Modal */}
      <EditModal
        record={editingRecord}
        open={editModalOpen}
        onClose={handleCloseEdit}
        onSave={handleSaveEdit}
      />

      <Footer />
    </Layout>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useSearchParams, Link } from 'react-router-dom';
import { ExternalLink, Filter, X, BarChart3, Download, FileSpreadsheet } from 'lucide-react';
import { generateInsightReport } from '@/lib/reports';

const NAVY = '#1a2744';
const GOLD = '#c9a03a';
const WHITE = '#ffffff';
const LIGHT_GRAY = '#f8f9fa';
const BORDER = '#e9ecef';
const TEXT = '#212529';
const MUTED = '#6c757d';
const GREEN = '#198754';
const RED = '#dc3545';

interface ListingDetail {
  title: string;
  price: number;
  currency: string;
  priceUSD: number;
  dial: string;
  date: string;
  region?: string;
  phone?: string;
  condition?: string;
  boxPapers?: string;
  confidence?: {
    score: number;
    aiFields: string[];
    catalogFields: string[];
  };
}

interface InsightData {
  success: boolean;
  reference: string;
  brand: string;
  model: string;
  primaryDial: string;
  dateRange: string;
  liquidity?: { buyers?: number; sellers?: number; buyerSellerRatio?: number };
  statsOriginal: {
    dataPoints: number;
    min: number;
    avg: number;
    max: number;
  };
  duplicated: {
    count: number;
    prices: number[];
  };
  statsFiltered: {
    dataPoints: number;
    min: number;
    avg: number;
    max: number;
  };
  outliers: {
    count: number;
    prices: number[];
  };
  listings: ListingDetail[];
}

export default function InsightDetails() {
  const [searchParams] = useSearchParams();
  const [ref, setRef] = useState(searchParams.get('ref') || '52506');
  const [data, setData] = useState<InsightData | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [selectedListing, setSelectedListing] = useState<ListingDetail | null>(null);

  const fetchData = useCallback(async (reference: string) => {
    setLoading(true);
    setError('');
    try {
      const res = await fetch(`/api/price-research?reference=${encodeURIComponent(reference)}`);
      const apiData = await res.json();
      if (!apiData.success) {
        setError(apiData.error || 'No data');
        setLoading(false);
        return;
      }

      // Compute stats from actual listings
      const prices = apiData.listings.map((l: any) => l.priceUSD);
      const sorted = [...prices].sort((a, b) => a - b);
      const q1 = sorted[Math.floor(sorted.length * 0.25)];
      const q3 = sorted[Math.floor(sorted.length * 0.75)];
      const iqr = q3 - q1;
      const lowerBound = q1 - 1.5 * iqr;
      const upperBound = q3 + 1.5 * iqr;

      // Detect outliers
      const outlierPrices = prices.filter((p: number) => p < lowerBound || p > upperBound);
      const filteredPrices = prices.filter((p: number) => p >= lowerBound && p <= upperBound);

      // Detect duplicates
      const priceCounts: Record<number, number> = {};
      prices.forEach((p: number) => { priceCounts[p] = (priceCounts[p] || 0) + 1; });
      const dupPrices = Object.entries(priceCounts)
        .filter(([, count]) => count > 1)
        .map(([price]) => Number(price));

      const insight: InsightData = {
        success: true,
        reference: apiData.reference,
        brand: apiData.brand,
        model: apiData.model,
        primaryDial: apiData.primaryDial,
        dateRange: 'Jun 24 \u2014 Dec 21',
        liquidity: apiData.liquidity,
        statsOriginal: {
          dataPoints: apiData.statsBefore?.count || prices.length,
          min: apiData.statsBefore?.min || Math.min(...prices),
          avg: apiData.statsBefore?.avg || Math.round(prices.reduce((a: number, b: number) => a + b, 0) / prices.length),
          max: apiData.statsBefore?.max || Math.max(...prices),
        },
        duplicated: {
          count: apiData.duplicates || dupPrices.length,
          prices: dupPrices,
        },
        statsFiltered: {
          dataPoints: filteredPrices.length,
          min: Math.min(...filteredPrices),
          avg: Math.round(filteredPrices.reduce((a: number, b: number) => a + b, 0) / filteredPrices.length),
          max: Math.max(...filteredPrices),
        },
        outliers: {
          count: outlierPrices.length,
          prices: outlierPrices.sort((a: number, b: number) => a - b),
        },
        listings: apiData.listings,
      };

      setData(insight);
    } catch {
      setError('Failed to fetch');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { fetchData(ref); }, [ref, fetchData]);

  const handleDownload = () => {
    if (!data) return;
    generateInsightReport(
      data.reference,
      data.brand,
      data.model,
      data.statsOriginal,
      data.statsFiltered,
      data.duplicated,
      data.outliers,
      data.listings,
      data.liquidity
    );
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center" style={{ backgroundColor: WHITE }}>
        <div className="animate-spin w-8 h-8 border-2 rounded-full" style={{ borderColor: GOLD, borderTopColor: 'transparent' }} />
      </div>
    );
  }

  return (
    <div style={{ backgroundColor: WHITE, color: TEXT, fontFamily: "'Inter', system-ui, sans-serif", minHeight: '100vh' }}>
      <NavBar />

      {/* Header */}
      <div style={{ backgroundColor: NAVY, color: WHITE, padding: '32px 0' }}>
        <div className="max-w-6xl mx-auto px-4">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-2xl font-bold mb-1" style={{ fontFamily: "'Playfair Display', serif" }}>Insight Details</h1>
              <p style={{ color: 'rgba(255,255,255,0.6)', fontSize: 14 }}>
                Deep-dive analytics per reference ΓÇö original stats, filtering, outliers, and all listings.
              </p>
            </div>
            {data && (
              <button
                onClick={handleDownload}
                style={{ padding: '10px 20px', borderRadius: 8, backgroundColor: GOLD, color: NAVY, border: 'none', fontSize: 14, fontWeight: 600, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 8 }}>
                <Download size={16} /> Export Report
              </button>
            )}
          </div>
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-4 py-8">
        {/* Search */}
        <div className="flex gap-2 mb-8">
          <div className="flex-1 relative">
            <input
              type="text"
              value={ref}
              onChange={e => setRef(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && fetchData(ref)}
              placeholder="Enter reference..."
              style={{ width: '100%', padding: '12px 16px', borderRadius: 8, border: `1px solid ${BORDER}`, fontSize: 14, outline: 'none' }}
            />
          </div>
          <button
            onClick={() => fetchData(ref)}
            style={{ padding: '12px 24px', borderRadius: 8, backgroundColor: GOLD, color: WHITE, border: 'none', fontWeight: 600, fontSize: 14, cursor: 'pointer' }}>
            Search
          </button>
        </div>

        {error && (
          <div style={{ padding: 16, borderRadius: 8, marginBottom: 24, backgroundColor: '#fff5f5', border: '1px solid #fecaca', color: RED, fontSize: 14 }}>
            {error}
          </div>
        )}

        {data && (
          <>
            {/* Watch Identity */}
            <div className="mb-8" style={{ padding: '24px 0', borderBottom: `1px solid ${BORDER}` }}>
              <div style={{ fontSize: 13, color: MUTED, textTransform: 'uppercase', letterSpacing: 1, marginBottom: 4 }}>{data.brand}</div>
              <div className="flex items-baseline gap-3 mb-3">
                <h2 style={{ fontSize: 28, fontWeight: 700, color: TEXT }}>{data.model}</h2>
                <span style={{ fontSize: 18, color: GOLD, fontFamily: 'monospace' }}>{data.reference}</span>
              </div>
              <div className="flex gap-6 flex-wrap" style={{ fontSize: 14, color: MUTED }}>
                <span>Dial: <strong style={{ color: TEXT }}>{data.primaryDial}</strong></span>
                <span>Condition: <strong style={{ color: TEXT }}>Any</strong></span>
                <span>Range: <strong style={{ color: TEXT }}>{data.dateRange}</strong></span>
                {data.liquidity?.buyers !== undefined && (
                  <span>B/S Ratio: <strong style={{ color: (data.liquidity.buyerSellerRatio || 0) > 1 ? RED : GREEN }}>{data.liquidity.buyerSellerRatio?.toFixed(2)}</strong></span>
                )}
              </div>
              {data.liquidity?.buyers !== undefined && (
                <div className="mt-3" style={{ maxWidth: 300 }}>
                  <div className="flex items-center justify-between mb-1">
                    <span style={{ fontSize: 12, color: MUTED }}>Buyers: {data.liquidity.buyers}</span>
                    <span style={{ fontSize: 12, color: MUTED }}>Sellers: {data.liquidity.sellers}</span>
                  </div>
                  <div style={{ width: '100%', height: 8, backgroundColor: BORDER, borderRadius: 4, overflow: 'hidden', display: 'flex' }}>
                    <div style={{ width: `${(data.liquidity.buyers / (data.liquidity.buyers + (data.liquidity.sellers || 0))) * 100}%`, height: '100%', backgroundColor: RED }} />
                    <div style={{ width: `${((data.liquidity.sellers || 0) / (data.liquidity.buyers + (data.liquidity.sellers || 0))) * 100}%`, height: '100%', backgroundColor: GREEN }} />
                  </div>
                </div>
              )}
            </div>

            {/* Stats Grid */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
              {/* Original Stats */}
              <div style={{ backgroundColor: '#fff8f0', borderRadius: 12, padding: 24 }}>
                <div style={{ fontSize: 14, fontWeight: 700, color: NAVY, marginBottom: 16 }}>Stats (Original)</div>
                <div style={{ fontSize: 13, color: MUTED, marginBottom: 8 }}>Data Points: <strong style={{ color: TEXT }}>{data.statsOriginal.dataPoints}</strong></div>
                <div style={{ fontSize: 13, color: MUTED, marginBottom: 8 }}>Min: <strong style={{ color: TEXT }}>${data.statsOriginal.min.toLocaleString()}</strong></div>
                <div style={{ fontSize: 13, color: MUTED, marginBottom: 8 }}>Avg: <strong style={{ color: TEXT }}>${data.statsOriginal.avg.toLocaleString()}</strong></div>
                <div style={{ fontSize: 13, color: MUTED }}>Max: <strong style={{ color: TEXT }}>${data.statsOriginal.max.toLocaleString()}</strong></div>
              </div>

              {/* Removed */}
              <div style={{ backgroundColor: '#fef2f2', borderRadius: 12, padding: 24 }}>
                <div style={{ fontSize: 14, fontWeight: 700, color: RED, marginBottom: 16 }}>Removed</div>
                <div style={{ fontSize: 13, color: MUTED, marginBottom: 12 }}>
                  Duplicated: <strong style={{ color: RED }}>{data.duplicated.count}</strong>
                  {data.duplicated.prices.length > 0 && (
                    <div className="flex flex-wrap gap-1 mt-1">
                      {data.duplicated.prices.map((price, i) => (
                        <span key={i} style={{ padding: '2px 8px', borderRadius: 4, backgroundColor: '#fee2e2', color: RED, fontSize: 11 }}>${price.toLocaleString()}</span>
                      ))}
                    </div>
                  )}
                </div>
                <div style={{ fontSize: 13, color: MUTED }}>
                  Outliers: <strong style={{ color: RED }}>{data.outliers.count}</strong>
                  {data.outliers.prices.length > 0 && (
                    <div className="flex flex-wrap gap-1 mt-1">
                      {data.outliers.prices.map((price, i) => (
                        <span key={i} style={{ padding: '2px 8px', borderRadius: 4, backgroundColor: '#fee2e2', color: RED, fontSize: 11 }}>${price.toLocaleString()}</span>
                      ))}
                    </div>
                  )}
                </div>
              </div>

              {/* Filtered Stats */}
              <div style={{ backgroundColor: '#f0f8f0', borderRadius: 12, padding: 24 }}>
                <div style={{ fontSize: 14, fontWeight: 700, color: NAVY, marginBottom: 16 }}>Stats (Filtered)</div>
                <div style={{ fontSize: 13, color: MUTED, marginBottom: 8 }}>Data Points: <strong style={{ color: TEXT }}>{data.statsFiltered.dataPoints}</strong></div>
                <div style={{ fontSize: 13, color: MUTED, marginBottom: 8 }}>Min: <strong style={{ color: TEXT }}>${data.statsFiltered.min.toLocaleString()}</strong></div>
                <div style={{ fontSize: 13, color: MUTED, marginBottom: 8 }}>Avg: <strong style={{ color: TEXT }}>${data.statsFiltered.avg.toLocaleString()}</strong></div>
                <div style={{ fontSize: 13, color: MUTED }}>Max: <strong style={{ color: TEXT }}>${data.statsFiltered.max.toLocaleString()}</strong></div>
              </div>
            </div>

            {/* Listings Table */}
            <div style={{ backgroundColor: WHITE, borderRadius: 12, border: `1px solid ${BORDER}`, overflow: 'hidden', marginBottom: 32 }}>
              <div style={{ padding: '16px 24px', borderBottom: `1px solid ${BORDER}`, fontWeight: 600, fontSize: 15, color: NAVY }}>
                Listings ({data.listings.length})
              </div>
              {data.listings.map((listing, idx) => {
                const conf = listing.confidence;
                const score = conf?.score || 0;
                const scoreColor = score === 100 ? GREEN : score >= 90 ? '#0d6efd' : score >= 80 ? '#fd7e14' : RED;
                const scoreLabel = score === 100 ? 'Γ£ô VERIFIED' : score >= 90 ? '≡ƒöì REVIEW' : score >= 80 ? 'ΓÜá CHECK' : '≡ƒÜ½ FLAGGED';
                return (
                  <div
                    key={idx}
                    onClick={() => setSelectedListing(listing)}
                    style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '12px 24px', borderBottom: `1px solid ${BORDER}`, cursor: 'pointer' }}
                    onMouseEnter={e => (e.currentTarget.style.backgroundColor = LIGHT_GRAY)}
                    onMouseLeave={e => (e.currentTarget.style.backgroundColor = WHITE)}>
                    <div style={{ width: 44, height: 44, borderRadius: 6, backgroundColor: LIGHT_GRAY, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 18, flexShrink: 0, color: MUTED }}>ΓîÜ</div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontSize: 13, color: TEXT, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{listing.title}</div>
                      <div style={{ fontSize: 12, color: MUTED, marginTop: 2 }}>
                        {listing.region && <span className="mr-2">{listing.region}</span>}
                        {listing.phone && <span className="mr-2">{listing.phone}</span>}
                        {listing.date && <span>{listing.date}</span>}
                      </div>
                      {conf && (
                        <div style={{ marginTop: 4, display: 'flex', alignItems: 'center', gap: 6 }}>
                          <span style={{ padding: '2px 8px', borderRadius: 4, fontSize: 11, fontWeight: 600, backgroundColor: scoreColor + '20', color: scoreColor }}>
                            {score}% {scoreLabel}
                          </span>
                          {conf.aiFields.length > 0 && (
                            <span style={{ fontSize: 11, color: MUTED }}>AI: {conf.aiFields.join(', ')}</span>
                          )}
                        </div>
                      )}
                    </div>
                    <div style={{ textAlign: 'right', flexShrink: 0 }}>
                      <div style={{ fontSize: 14, fontWeight: 600, color: GOLD }}>${listing.priceUSD?.toLocaleString()}</div>
                      <div style={{ fontSize: 11, color: MUTED }}>{listing.price?.toLocaleString()} {listing.currency}</div>
                    </div>
                    <ExternalLink className="w-3.5 h-3.5" style={{ color: MUTED, flexShrink: 0 }} />
                  </div>
                );
              })}
            </div>
          </>
        )}

        <Footer />
      </div>

      {/* Listing Modal */}
      {selectedListing && data && (
        <ListingModal listing={selectedListing} data={data} onClose={() => setSelectedListing(null)} />
      )}
    </div>
  );
}

function ListingModal({ listing, data, onClose }: { listing: ListingDetail; data: InsightData; onClose: () => void }) {
  const [isEditing, setIsEditing] = useState(false);
  const [editedDial, setEditedDial] = useState(listing.dial);
  const [editedPrice, setEditedPrice] = useState(listing.price.toString());
  const [editedCurrency, setEditedCurrency] = useState(listing.currency);
  const [editedRegion, setEditedRegion] = useState(listing.region || '');
  const [editedPhone, setEditedPhone] = useState(listing.phone || '');

  const conf = listing.confidence;
  const score = conf?.score || 0;
  const scoreColor = score === 100 ? GREEN : score >= 90 ? '#0d6efd' : score >= 80 ? '#fd7e14' : RED;
  const scoreLabel = score === 100 ? 'Γ£ô VERIFIED' : score >= 90 ? '≡ƒöì REVIEW' : score >= 80 ? 'ΓÜá CHECK' : '≡ƒÜ½ FLAGGED';

  const handleSave = () => {
    // In production, this would POST to an API to save back to pipeline
    console.log('Saving edited listing:', {
      ...listing,
      dial: editedDial,
      price: Number(editedPrice),
      currency: editedCurrency,
      region: editedRegion,
      phone: editedPhone,
    });
    setIsEditing(false);
  };

  return (
    <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.5)', zIndex: 100, display: 'flex', alignItems: 'center', justifyContent: 'center' }} onClick={onClose}>
      <div style={{ backgroundColor: WHITE, borderRadius: 12, maxWidth: 600, width: '90%', maxHeight: '85vh', overflow: 'auto' }} onClick={e => e.stopPropagation()}>
        <div style={{ padding: 24 }}>
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3">
              <h3 style={{ fontSize: 16, fontWeight: 600, color: NAVY }}>Post Information</h3>
              {conf && (
                <span style={{ padding: '3px 10px', borderRadius: 4, fontSize: 11, fontWeight: 600, backgroundColor: scoreColor + '20', color: scoreColor }}>
                  {score}% {scoreLabel}
                </span>
              )}
            </div>
            <button onClick={onClose} style={{ background: 'none', border: 'none', fontSize: 20, color: MUTED, cursor: 'pointer' }}>├ù</button>
          </div>

          {/* Confidence Detail */}
          {conf && (
            <div style={{ backgroundColor: LIGHT_GRAY, borderRadius: 8, padding: 16, marginBottom: 16 }}>
              <div style={{ fontSize: 13, fontWeight: 600, color: NAVY, marginBottom: 8 }}>Confidence Breakdown</div>
              <div className="grid grid-cols-2 gap-2" style={{ fontSize: 12 }}>
                <div>
                  <span style={{ color: GREEN, fontWeight: 600 }}>Catalog Fields:</span>
                  <div style={{ color: MUTED }}>{conf.catalogFields.join(', ') || 'None'}</div>
                </div>
                <div>
                  <span style={{ color: RED, fontWeight: 600 }}>AI Fields:</span>
