        {!enrichment && (
          <button
            onClick={onEnrich}
            className="flex items-center gap-1.5 px-2 py-1 rounded bg-bg-card border border-border-default text-[10px] text-text-secondary hover:text-text-primary transition-colors"
          >
            <TrendingUp size={10} />
            Fetch Market Data
          </button>
        )}
        {enrichment?.officialUrl && (
          <a href={enrichment.officialUrl} target="_blank" rel="noopener noreferrer"
            className="flex items-center gap-1 px-2 py-1 rounded bg-bg-card border border-border-default text-[10px] text-text-secondary hover:text-gold-primary transition-colors">
            <ExternalLink size={10} />
            Official Site
          </a>
        )}
      </div>
    </div>
  );
}

export default function ReviewPage() {
  const { records, stats, loading } = useWatchData();
  const [filterMinConfidence, setFilterMinConfidence] = useState(0);
  const [filterMaxConfidence, setFilterMaxConfidence] = useState(100);
  const [filterDial, setFilterDial] = useState<string>('all');
  const [filterBrand, setFilterBrand] = useState<string>('all');
  const [filterVerdict, setFilterVerdict] = useState<'all' | 'APPROVED' | 'HUMAN' | 'RECYCLE'>('all');
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [editingRecord, setEditingRecord] = useState<WatchRecord | null>(null);
  const [editForm, setEditForm] = useState<Partial<WatchRecord>>({});
  const [suggestionsMap, setSuggestionsMap] = useState<Record<string, Suggestion[]>>({});
  const [aiLoading, setAiLoading] = useState<Record<string, boolean>>({});
  const [savedIds, setSavedIds] = useState<Set<string>>(new Set());
  const [bulkProgress, setBulkProgress] = useState<{ done: number; total: number } | null>(null);
  const [verifyMap, setVerifyMap] = useState<Record<string, VerifyImageResult>>({});
  const [verifyLoading, setVerifyLoading] = useState<Record<string, boolean>>({});
  const [enrichMap, setEnrichMap] = useState<Record<string, EnrichmentData>>({});
  const [enrichLoading, setEnrichLoading] = useState<Record<string, boolean>>({});

  const brands = useMemo(() => {
    const set = new Set(records.map(r => r.brand).filter(Boolean));
    return Array.from(set).sort();
  }, [records]);

  const dials = useMemo(() => {
    const set = new Set(records.map(r => r.dialColor).filter(Boolean));
    return Array.from(set).sort();
  }, [records]);

  const filtered = useMemo(() => {
    return records.filter(r => {
      if (r.confidence < filterMinConfidence || r.confidence > filterMaxConfidence) return false;
      if (filterDial !== 'all' && r.dialColor !== filterDial) return false;
      if (filterBrand !== 'all' && r.brand !== filterBrand) return false;
      if (filterVerdict !== 'all') {
        const v = r.isResidue || r.confidence < 35 ? 'RECYCLE' : r.confidence >= 90 && !r.failureFlags?.length ? 'APPROVED' : 'HUMAN';
        if (v !== filterVerdict) return false;
      }
      return true;
    }).sort((a, b) => a.confidence - b.confidence);
  }, [records, filterMinConfidence, filterMaxConfidence, filterDial, filterBrand, filterVerdict]);

  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [keyboardHelp, setKeyboardHelp] = useState(false);

  const toggleExpand = useCallback((id: string) => {
    setExpandedId(prev => prev === id ? null : id);
  }, []);

  const startEdit = useCallback((record: WatchRecord) => {
    setEditingRecord(record);
    setEditForm({
      reference: record.reference,
      dialColor: record.dialColor,
      brand: record.brand,
      price: record.price,
      condition: record.condition,
    });
  }, []);

  const cancelEdit = useCallback(() => {
    setEditingRecord(null);
    setEditForm({});
  }, []);

  const saveEdit = useCallback(async () => {
    if (!editingRecord) return;
    // POST to catalog-feedback API ΓåÆ Supabase catalog_feedback table
    // This is the training signal that improves future parse accuracy
    try {
      const resp = await fetch('/api/catalog-feedback', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          reference: editForm.reference || editingRecord.reference,
          brand: editForm.brand || editingRecord.brand,
          collection: editForm.family || null,
          model: (editForm as any).model || null,
          dialColor: editForm.dialColor || editingRecord.dialColor,
          source: 'human_approval',
          originalGuess: {
            brand: editingRecord.brand,
            reference: editingRecord.reference,
            dialColor: editingRecord.dialColor,
          },
          rawMessage: editingRecord.rawMessage,
        }),
      });
      const data = await resp.json();
      if (data.success) {
        setSavedIds(prev => new Set(prev).add(editingRecord.id));
        setEditingRecord(null);
        setEditForm({});
      } else {
        console.error('[saveEdit] API returned error:', data);
        alert(`Save failed: ${data.error || 'unknown error'}`);
      }
    } catch (e: any) {
      console.error('[saveEdit] Network error:', e);
      alert(`Save failed: ${e?.message || String(e)}`);
    }
  }, [editingRecord, editForm]);

  // Build field-level suggestions from a Kimi parse result vs the current record.
  const buildSuggestions = useCallback((record: WatchRecord, parsed: any, source: string): Suggestion[] => {
    const suggestions: Suggestion[] = [];
    const src = source as Suggestion['source'];
    if (parsed.dialColor && parsed.dialColor.toUpperCase() !== (record.dialColor || '').toUpperCase()) {
      suggestions.push({ field: 'dialColor', value: parsed.dialColor, reason: `${source} suggests ${parsed.dialColor} from reference/context analysis`, source: src });
    }
    if (parsed.reference && parsed.reference.toUpperCase() !== (record.reference || '').toUpperCase()) {
      suggestions.push({ field: 'reference', value: parsed.reference, reason: `${source} parsed full reference with suffix`, source: src });
    }
    if (parsed.brand && parsed.brand !== 'Unknown' && parsed.brand !== record.brand) {
      suggestions.push({ field: 'brand', value: parsed.brand, reason: `${source} identified brand from reference pattern`, source: src });
    }
    return suggestions;
  }, []);

  // Keyboard shortcuts
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
      const visible = filtered.slice(0, 200);
      const currentIdx = expandedId ? visible.findIndex(r => r.id === expandedId) : -1;

      switch (e.key.toLowerCase()) {
        case 'n': // Next
          e.preventDefault();
          if (currentIdx >= 0 && currentIdx < visible.length - 1) {
            setExpandedId(visible[currentIdx + 1].id);
          } else if (visible.length > 0) {
            setExpandedId(visible[0].id);
          }
          break;
        case 'p': // Previous
          e.preventDefault();
          if (currentIdx > 0) {
            setExpandedId(visible[currentIdx - 1].id);
          }
          break;
        case 'e': // Edit
          e.preventDefault();
          if (expandedId) {
            const r = visible.find(r => r.id === expandedId);
            if (r) startEdit(r);
          }
          break;
        case 'a': // Approve
          e.preventDefault();
          if (expandedId) {
            setSavedIds(prev => new Set(prev).add(expandedId));
          }
          break;
        case 'r': // Recycle
          e.preventDefault();
          if (expandedId) {
            // Mark as recycled (visual only for now)
            setSavedIds(prev => { const s = new Set(prev); s.delete(expandedId); return s; });
          }
          break;
        case 's': // Select for bulk
          e.preventDefault();
          if (expandedId) {
            setSelectedIds(prev => {
              const s = new Set(prev);
              if (s.has(expandedId)) s.delete(expandedId);
              else s.add(expandedId);
              return s;
            });
          }
          break;
        case '?':
        case 'h':
          e.preventDefault();
          setKeyboardHelp(prev => !prev);
          break;
        case 'escape':
          setExpandedId(null);
          setEditingRecord(null);
          setKeyboardHelp(false);
          break;
      }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [filtered, expandedId, startEdit]);

  const parseOne = useCallback(async (record: WatchRecord): Promise<Suggestion[]> => {
    const res = await fetch('/api/ai-parse', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        rawMessage: record.rawMessage,
        currentGuess: {
          reference: record.reference,
          dialColor: record.dialColor,
          brand: record.brand,
          price: record.price,
          currency: record.originalCurrency,
        },
      }),
    });
    const data = await res.json();
    if (data.success && data.parsed) {
      return buildSuggestions(record, data.parsed, data.source || 'kimi');
    }
    return [];
  }, [buildSuggestions]);

  const askAI = useCallback(async (record: WatchRecord) => {
    setAiLoading(prev => ({ ...prev, [record.id]: true }));
    try {
      const suggestions = await parseOne(record);
      setSuggestionsMap(prev => ({ ...prev, [record.id]: suggestions }));
    } catch (e) {
      console.error('AI parse failed:', e);
    } finally {
      setAiLoading(prev => ({ ...prev, [record.id]: false }));
    }
  }, [parseOne]);

  // Verify the photo matches the text-extracted reference (image read blind).
  const verifyImage = useCallback(async (record: WatchRecord) => {
    if (!record.imageUrl) return;
    setVerifyLoading(prev => ({ ...prev, [record.id]: true }));
    try {
      const result = await verifyImageReference(record.imageUrl, record.reference, record.brand);
      setVerifyMap(prev => ({ ...prev, [record.id]: result }));
    } catch (e) {
      console.error('Image verify failed:', e);
    } finally {
      setVerifyLoading(prev => ({ ...prev, [record.id]: false }));
    }
  }, []);

  // Bulk re-parse all currently-filtered records with Kimi (concurrency-limited).
  const bulkReparse = useCallback(async (targets: WatchRecord[]) => {
    const queue = targets.slice(0, 50); // safety cap per run
    if (queue.length === 0) return;
    setBulkProgress({ done: 0, total: queue.length });
    const CONCURRENCY = 4;
    let idx = 0;
    let done = 0;
    const worker = async () => {
      while (idx < queue.length) {
        const record = queue[idx++];
        try {
          const suggestions = await parseOne(record);
          if (suggestions.length > 0) {
            setSuggestionsMap(prev => ({ ...prev, [record.id]: suggestions }));
          }
        } catch (e) {
          console.error('Bulk parse failed for', record.id, e);
        } finally {
          done++;
          setBulkProgress({ done, total: queue.length });
        }
      }
    };
    await Promise.all(Array.from({ length: CONCURRENCY }, worker));
    setBulkProgress(null);
  }, [parseOne]);

  // Bulk enrich all currently-filtered records with structured market data
  const bulkEnrich = useCallback(async (targets: WatchRecord[]) => {
    const queue = targets.filter(r => r.reference).slice(0, 50);
    if (queue.length === 0) return;
    setBulkProgress({ done: 0, total: queue.length });
    const CONCURRENCY = 4;
    let idx = 0;
    let done = 0;
    const worker = async () => {
      while (idx < queue.length) {
        const record = queue[idx++];
        try {
          const data = await enrichWatch(record.reference!, record.brand);
          if (data.success && data.enrichment) {
            setEnrichMap(prev => ({ ...prev, [record.id]: data.enrichment! }));
          }
        } catch (e) {
          console.error('Bulk enrich failed for', record.id, e);
        } finally {
          done++;
          setBulkProgress({ done, total: queue.length });
        }
      }
    };
    await Promise.all(Array.from({ length: CONCURRENCY }, worker));
    setBulkProgress(null);
  }, []);

  const applySuggestion = useCallback((recordId: string, suggestion: Suggestion) => {
    setEditForm(prev => ({ ...prev, [suggestion.field]: suggestion.value }));
    // If we're not in edit mode, start editing
    const record = records.find(r => r.id === recordId);
    if (record && !editingRecord) {
      startEdit(record);
      setEditForm({ [suggestion.field]: suggestion.value });
    }
  }, [records, editingRecord, startEdit]);

  // Enrich a single record with structured market data
  const handleEnrich = useCallback(async (record: WatchRecord) => {
    if (!record.reference) return;
    setEnrichLoading(prev => ({ ...prev, [record.id]: true }));
    try {
      const data = await enrichWatch(record.reference, record.brand);
      if (data.success && data.enrichment) {
        setEnrichMap(prev => ({ ...prev, [record.id]: data.enrichment! }));
      }
    } catch (e) {
      console.error('Enrich failed:', e);
    } finally {
      setEnrichLoading(prev => ({ ...prev, [record.id]: false }));
    }
  }, []);

  if (loading) {
    return (
      <Layout {...stats}>
        <TabNav totalProcessed={stats.totalProcessed} />
        <div className="p-8 text-center text-text-muted">Loading records...</div>
      </Layout>
    );
  }

  return (
    <Layout {...stats}>
      <TabNav totalProcessed={stats.totalProcessed} />

      <div className="p-5 max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-6 flex items-start justify-between gap-4 flex-wrap">
          <div>
            <h1 className="text-2xl font-bold text-text-primary flex items-center gap-2">
              <Eye size={24} className="text-gold-primary" />
              Human Review Mode
            </h1>
            <p className="text-sm text-text-muted mt-1">
              Review low-confidence parses, fix errors, and train the catalog. 
              {filtered.length} records match current filters.
            </p>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => bulkEnrich(filtered)}
              disabled={bulkProgress !== null || filtered.length === 0}
              className="flex items-center gap-2 px-4 py-2 rounded-lg bg-emerald-500/10 border border-emerald-500/40 text-emerald-400 text-sm font-medium hover:bg-emerald-500/20 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              title="Enrich all filtered records with catalog + market data"
            >
              <TrendingUp size={16} />
              {bulkProgress
                ? `EnrichingΓÇª ${bulkProgress.done}/${bulkProgress.total}`
                : `Bulk Enrich (${Math.min(filtered.length, 50)})`}
            </button>
            <button
              onClick={() => bulkReparse(filtered)}
              disabled={bulkProgress !== null || filtered.length === 0}
              className="flex items-center gap-2 px-4 py-2 rounded-lg bg-gold-primary/10 border border-gold-primary/40 text-gold-primary text-sm font-medium hover:bg-gold-primary/20 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              title="Re-parse the filtered records with Kimi K2.6 and surface suggestions"
            >
              <Wand2 size={16} />
              {bulkProgress
                ? `Kimi re-parsingΓÇª ${bulkProgress.done}/${bulkProgress.total}`
                : `Bulk Kimi Re-parse (${Math.min(filtered.length, 50)})`}
            </button>
          </div>
        </div>

        {/* Filters */}
        <div className="bg-bg-card border border-border-default rounded-lg p-4 mb-6 flex flex-wrap gap-4 items-end">
          <div>
            <label className="text-xs text-text-muted uppercase tracking-wider block mb-1">Min Confidence</label>
            <select
              value={filterMinConfidence}
              onChange={e => setFilterMinConfidence(Number(e.target.value))}
              className="bg-bg-elevated border border-border-default rounded px-3 py-1.5 text-sm text-text-primary"
            >
              <option value={0}>0%</option>
              <option value={50}>50%</option>
              <option value={60}>60%</option>
              <option value={70}>70%</option>
              <option value={80}>80%</option>
              <option value={90}>90%</option>
            </select>
          </div>
          <div>
            <label className="text-xs text-text-muted uppercase tracking-wider block mb-1">Max Confidence</label>
            <select
              value={filterMaxConfidence}
              onChange={e => setFilterMaxConfidence(Number(e.target.value))}
              className="bg-bg-elevated border border-border-default rounded px-3 py-1.5 text-sm text-text-primary"
            >
              <option value={100}>100%</option>
              <option value={90}>90%</option>
              <option value={80}>80%</option>
              <option value={70}>70%</option>
              <option value={60}>60%</option>
              <option value={50}>50%</option>
            </select>
          </div>
          <div>
            <label className="text-xs text-text-muted uppercase tracking-wider block mb-1">Brand</label>
            <select
              value={filterBrand}
              onChange={e => setFilterBrand(e.target.value)}
              className="bg-bg-elevated border border-border-default rounded px-3 py-1.5 text-sm text-text-primary"
            >
              <option value="all">All Brands</option>
              {brands.map(b => (
                <option key={b} value={b}>{b}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="text-xs text-text-muted uppercase tracking-wider block mb-1">Dial Color</label>
            <select
              value={filterDial}
              onChange={e => setFilterDial(e.target.value)}
              className="bg-bg-elevated border border-border-default rounded px-3 py-1.5 text-sm text-text-primary"
            >
              <option value="all">All Dials</option>
              {dials.map(d => (
                <option key={d} value={d}>{d}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="text-xs text-text-muted uppercase tracking-wider block mb-1">Verdict</label>
            <select
              value={filterVerdict}
              onChange={e => setFilterVerdict(e.target.value as any)}
              className="bg-bg-elevated border border-border-default rounded px-3 py-1.5 text-sm text-text-primary"
            >
              <option value="all">All Verdicts</option>
              <option value="APPROVED">APPROVED</option>
              <option value="HUMAN">HUMAN</option>
              <option value="RECYCLE">RECYCLE</option>
            </select>
          </div>
          <button
            onClick={() => {
              setFilterMinConfidence(0);
              setFilterMaxConfidence(100);
              setFilterBrand('all');
              setFilterDial('all');
              setFilterVerdict('all');
            }}
            className="flex items-center gap-1 text-xs text-text-muted hover:text-text-primary transition-colors"
          >
            <RotateCcw size={12} />
            Reset
          </button>
        </div>

        {/* Keyboard Help */}
        {keyboardHelp && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center" onClick={() => setKeyboardHelp(false)}>
            <div className="bg-bg-card border border-border-default rounded-xl p-6 max-w-sm w-full mx-4" onClick={e => e.stopPropagation()}>
              <h3 className="text-lg font-bold text-text-primary mb-4">Keyboard Shortcuts</h3>
              <div className="space-y-2 text-sm">
                <div className="flex justify-between"><span className="text-text-secondary">N</span><span className="text-text-muted">Next record</span></div>
                <div className="flex justify-between"><span className="text-text-secondary">P</span><span className="text-text-muted">Previous record</span></div>
                <div className="flex justify-between"><span className="text-text-secondary">E</span><span className="text-text-muted">Edit fields</span></div>
                <div className="flex justify-between"><span className="text-text-secondary">A</span><span className="text-text-muted">Approve record</span></div>
                <div className="flex justify-between"><span className="text-text-secondary">R</span><span className="text-text-muted">Recycle record</span></div>
                <div className="flex justify-between"><span className="text-text-secondary">S</span><span className="text-text-muted">Select for bulk</span></div>
                <div className="flex justify-between"><span className="text-text-secondary">H / ?</span><span className="text-text-muted">Toggle this help</span></div>
                <div className="flex justify-between"><span className="text-text-secondary">Esc</span><span className="text-text-muted">Close / Cancel</span></div>
              </div>
              <button onClick={() => setKeyboardHelp(false)} className="mt-4 w-full py-2 rounded bg-gold-primary/20 text-gold-primary text-sm font-medium">Close</button>
            </div>
          </div>
        )}

        {/* Records List */}
        <div className="space-y-3">
          {filtered.slice(0, 200).map(record => {
            const isExpanded = expandedId === record.id;
            const isEditing = editingRecord?.id === record.id;
            const suggestions = suggestionsMap[record.id] || [];
            const isAiLoading = aiLoading[record.id];
            const isSaved = savedIds.has(record.id);
            const isSelected = selectedIds.has(record.id);

            let confidenceColor = 'text-emerald-400';
            if (record.confidence < 60) confidenceColor = 'text-red-400';
            else if (record.confidence < 80) confidenceColor = 'text-amber-400';

            return (
              <div
                key={record.id}
                className={`bg-bg-card border rounded-lg transition-all ${
                  isExpanded ? 'border-gold-primary/50' : isSelected ? 'border-cyan-400/50' : 'border-border-default hover:border-border-hover'
                }`}
              >
                {/* Summary Row */}
                <div
                  className="flex items-center gap-4 p-4 cursor-pointer"
                  onClick={() => toggleExpand(record.id)}
                >
                  <div className="flex items-center gap-2 flex-shrink-0">
                    {isSelected && <div className="w-2 h-2 rounded-full bg-cyan-400" />}
                    {record.confidence < 60 ? (
                      <AlertTriangle size={18} className="text-red-400" />
                    ) : record.confidence < 80 ? (
                      <HelpCircle size={18} className="text-amber-400" />
                    ) : (
                      <CheckCircle size={18} className="text-emerald-400" />
                    )}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-3 flex-wrap">
                      <span className="font-bold text-text-primary">{record.reference}</span>
                      <span className="text-xs px-2 py-0.5 rounded bg-bg-elevated text-text-secondary">
                        {record.dialColor}
                      </span>
                      <span className="text-xs text-text-muted">{record.brand}</span>
                      <span className={`text-xs font-bold ${confidenceColor}`}>
                        {record.confidence}%
                      </span>
                      {isSaved && (
                        <span className="text-xs px-1.5 py-0.5 rounded bg-emerald-500/20 text-emerald-400">
                          Saved
                        </span>
                      )}
                    </div>
                    <div className="text-xs text-text-muted mt-0.5 truncate">
                      {record.rawMessage}
                    </div>
                  </div>
                  <div className="flex items-center gap-3 flex-shrink-0">
                    <div className="text-right">
                      <div className="text-sm font-bold text-text-primary">
                        ${record.price?.toLocaleString()}
                      </div>
                      <div className="text-xs text-text-muted">{record.originalCurrency}</div>
                    </div>
                    {isExpanded ? <ChevronUp size={16} className="text-text-muted" /> : <ChevronDown size={16} className="text-text-muted" />}
                  </div>
                </div>

                {/* Expanded Detail */}
                {isExpanded && (
                  <div className="border-t border-border-default px-4 pb-4">
                    {/* Original Message */}
                    <div className="mt-4 mb-4">
                      <label className="text-xs text-text-muted uppercase tracking-wider block mb-1">
                        Original WhatsApp Message
                      </label>
                      <div className="bg-bg-elevated border border-border-default rounded p-3 text-sm text-text-secondary font-mono whitespace-pre-wrap">
                        {record.rawMessage}
                      </div>
                    </div>

                    {/* Description */}
                    {record.description && (
                      <div className="mb-4">
                        <label className="text-xs text-text-muted uppercase tracking-wider block mb-1">
                          Extracted Description
                        </label>
                        <div className="text-sm text-text-primary">{record.description}</div>
                      </div>
                    )}

                    {/* Parsed Fields */}
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-4">
                      {isEditing ? (
                        <>
                          <div>
                            <label className="text-xs text-text-muted block mb-1">Reference</label>
                            <input
                              value={editForm.reference || ''}
                              onChange={e => setEditForm(p => ({ ...p, reference: e.target.value }))}
                              className="w-full bg-bg-elevated border border-border-default rounded px-2 py-1 text-sm text-text-primary"
                            />
                          </div>
                          <div>
                            <label className="text-xs text-text-muted block mb-1">Dial Color</label>
                            <input
                              value={editForm.dialColor || ''}
                              onChange={e => setEditForm(p => ({ ...p, dialColor: e.target.value }))}
                              className="w-full bg-bg-elevated border border-border-default rounded px-2 py-1 text-sm text-text-primary"
                            />
                          </div>
                          <div>
                            <label className="text-xs text-text-muted block mb-1">Brand</label>
                            <input
                              value={editForm.brand || ''}
                              onChange={e => setEditForm(p => ({ ...p, brand: e.target.value }))}
                              className="w-full bg-bg-elevated border border-border-default rounded px-2 py-1 text-sm text-text-primary"
                            />
                          </div>
                          <div>
                            <label className="text-xs text-text-muted block mb-1">Price USD</label>
                            <input
                              type="number"
                              value={editForm.price || 0}
                              onChange={e => setEditForm(p => ({ ...p, price: Number(e.target.value) }))}
                              className="w-full bg-bg-elevated border border-border-default rounded px-2 py-1 text-sm text-text-primary"
                            />
                          </div>
                        </>
                      ) : (
                        <>
                          <div className="bg-bg-elevated rounded p-2">
                            <div className="text-xs text-text-muted">Reference</div>
                            <div className="text-sm font-bold text-text-primary">{record.reference}</div>
                          </div>
                          <div className="bg-bg-elevated rounded p-2">
                            <div className="text-xs text-text-muted">Dial Color</div>
                            <div className="text-sm font-bold text-text-primary">{record.dialColor}</div>
                          </div>
                          <div className="bg-bg-elevated rounded p-2">
                            <div className="text-xs text-text-muted">Brand</div>
                            <div className="text-sm font-bold text-text-primary">{record.brand}</div>
                          </div>
                          <div className="bg-bg-elevated rounded p-2">
                            <div className="text-xs text-text-muted">Price (USD)</div>
                            <div className="text-sm font-bold text-text-primary">${record.price?.toLocaleString()}</div>
                          </div>
                        </>
                      )}
                    </div>

                    {/* Confidence Reasons */}
                    <div className="mb-4">
                      <label className="text-xs text-text-muted uppercase tracking-wider block mb-1">
                        Confidence Breakdown
                      </label>
                      <div className="flex flex-wrap gap-2">
                        {(record as any).confidenceReasons?.map((reason: string, i: number) => (
                          <span key={i} className="text-xs px-2 py-1 rounded bg-bg-elevated text-text-secondary capitalize">
                            {reason.replace(/_/g, ' ')}
                          </span>
                        )) || (
                          <span className="text-xs text-text-muted">Confidence computed from parsing quality</span>
                        )}
                      </div>
                    </div>

                    {/* AI Suggestions */}
                    {suggestions.length > 0 && (
                      <div className="mb-4">
                        <label className="text-xs text-text-muted uppercase tracking-wider block mb-1">
                          AI Suggestions
                        </label>
                        <div className="space-y-2">
                          {suggestions.map((s, i) => (
                            <div key={i} className="flex items-center gap-3 bg-bg-elevated rounded p-2">
                              <Wand2 size={14} className="text-gold-primary" />
                              <div className="flex-1">
                                <div className="text-sm text-text-primary">
                                  <span className="font-bold">{s.field}:</span> {s.value}
                                </div>
                                <div className="text-xs text-text-muted">{s.reason}</div>
                              </div>
                              <button
                                onClick={() => applySuggestion(record.id, s)}
                                className="text-xs px-2 py-1 rounded bg-gold-primary/20 text-gold-primary hover:bg-gold-primary/30 transition-colors"
                              >
                                Apply
                              </button>
                            </div>
                          ))}
                        </div>
                      </div>
                    )}

                    {/* Actions */}
                    <div className="flex items-center gap-3">
                      {isEditing ? (
                        <>
                          <button
                            onClick={saveEdit}
                            className="flex items-center gap-1.5 px-3 py-1.5 rounded bg-emerald-500/20 text-emerald-400 hover:bg-emerald-500/30 transition-colors text-sm"
                          >
                            <Save size={14} />
                            Save & Train Catalog
                          </button>
                          <button
                            onClick={cancelEdit}
                            className="px-3 py-1.5 rounded bg-bg-elevated text-text-muted hover:text-text-primary transition-colors text-sm"
                          >
                            Cancel
                          </button>
                        </>
                      ) : (
                        <>
                          <button
                            onClick={() => startEdit(record)}
                            className="flex items-center gap-1.5 px-3 py-1.5 rounded bg-gold-primary/20 text-gold-primary hover:bg-gold-primary/30 transition-colors text-sm"
                          >
                            Edit Fields
                          </button>
                          <button
                            onClick={() => askAI(record)}
                            disabled={isAiLoading}
                            className="flex items-center gap-1.5 px-3 py-1.5 rounded bg-bg-elevated text-text-secondary hover:text-text-primary transition-colors text-sm disabled:opacity-50"
                          >
                            <Wand2 size={14} />
                            {isAiLoading ? 'Asking AI...' : 'Ask AI'}
                          </button>
                          <button
                            onClick={() => handleEnrich(record)}
                            disabled={enrichLoading[record.id] || !record.reference}
                            className="flex items-center gap-1.5 px-3 py-1.5 rounded bg-bg-elevated text-text-secondary hover:text-text-primary transition-colors text-sm disabled:opacity-50"
                            title="Fetch catalog + market data for this reference"
                          >
                            <TrendingUp size={14} />
                            {enrichLoading[record.id] ? 'EnrichingΓÇª' : 'Enrich'}
                          </button>
                          {record.imageUrl && (
                            <button
                              onClick={() => verifyImage(record)}
                              disabled={verifyLoading[record.id]}
                              className="flex items-center gap-1.5 px-3 py-1.5 rounded bg-bg-elevated text-text-secondary hover:text-text-primary transition-colors text-sm disabled:opacity-50"
                              title="Read the photo blind and check it matches the reference"
                            >
                              <Eye size={14} />
                              {verifyLoading[record.id] ? 'VerifyingΓÇª' : 'Verify Image'}
                            </button>
                          )}
                        </>
                      )}
                    </div>

                    {/* Enrichment Results */}
                    {enrichMap[record.id] && (() => {
                      const e = enrichMap[record.id];
                      return (
                        <div className="mt-3 rounded-lg border border-gold-primary/30 bg-gold-primary/5 px-3 py-2">
                          <div className="flex items-center gap-2 mb-1">
                            <TrendingUp size={12} className="text-gold-primary" />
                            <span className="text-xs font-bold text-gold-primary uppercase tracking-wider">Enrichment</span>
                          </div>
                          <div className="flex flex-wrap gap-2">
                            {e.catalog?.collection && (
                              <span className="text-[10px] px-1.5 py-0.5 rounded bg-bg-elevated text-text-muted font-mono">
                                {e.catalog.collection}
                              </span>
                            )}
                            {e.catalog?.model && (
                              <span className="text-[10px] px-1.5 py-0.5 rounded bg-bg-elevated text-text-muted font-mono">
                                {e.catalog.model}
                              </span>
                            )}
                            {e.market?.chrono24?.priceRange && (
                              <span className="text-[10px] px-1.5 py-0.5 rounded bg-emerald-500/10 text-emerald-400 font-mono">
                                Chrono24: ${e.market.chrono24.priceRange.median.toLocaleString()}
                              </span>
                            )}
                            {e.officialUrl && (
                              <a href={e.officialUrl} target="_blank" rel="noopener noreferrer"
                                className="text-[10px] text-text-muted hover:text-gold-primary transition-colors flex items-center gap-0.5">
                                <ExternalLink size={10} /> Official
                              </a>
                            )}
                          </div>
                        </div>
                      );
                    })()}

                    {/* AI Assistance Panel */}
                    <AIAssistPanel 
                      record={record} 
                      enrichment={enrichMap[record.id]} 
                      onEnrich={() => handleEnrich(record)}
                    />

                    {/* Image-vs-reference verdict */}
                    {verifyMap[record.id] && (() => {
                      const v = verifyMap[record.id];
                      const styles = v.verdict === 'MISMATCH'
                        ? 'border-red-500/50 bg-red-500/10 text-red-300'
                        : v.verdict === 'MATCH'
                        ? 'border-emerald-500/40 bg-emerald-500/10 text-emerald-300'
                        : 'border-amber-500/40 bg-amber-500/10 text-amber-300';
                      const Icon = v.verdict === 'MISMATCH' ? AlertTriangle : v.verdict === 'MATCH' ? CheckCircle : HelpCircle;
                      return (
                        <div className={`mt-3 rounded-lg border px-3 py-2 text-xs ${styles}`}>
                          <div className="flex items-center gap-2 font-semibold">
                            <Icon size={14} />
                            {v.verdict === 'MISMATCH' ? 'ΓÜá IMAGE MISMATCH ΓÇö routed to human review' : v.verdict === 'MATCH' ? 'Image confirms reference' : 'Could not verify from image'}
                            {v.source && <span className="opacity-60 font-normal">┬╖ {v.source}</span>}
                          </div>
                          <div className="mt-1 opacity-90">{v.reason}</div>
                          {v.image && (
                            <div className="mt-1 opacity-70">
                              Image saw: {v.image.brand} / ref {v.image.referenceVisible} / {v.image.dialColor} (conf {v.image.confidence}%)
                            </div>
                          )}
                        </div>
                      );
                    })()}
                  </div>
                )}
              </div>
            );
          })}
        </div>

        {filtered.length === 0 && (
          <div className="text-center py-12 text-text-muted">
            No records match the current filters.
          </div>
        )}

        {filtered.length > 200 && (
          <div className="text-center py-4 text-xs text-text-muted">
            Showing 200 of {filtered.length} records. Use filters to narrow results.
          </div>
        )}
      </div>
    </Layout>
  );
}

import { useState, useMemo, useCallback, useRef, useEffect } from 'react';
import { Search, X, Filter, ChevronDown } from 'lucide-react';
import { Layout } from '@/components/Layout';
import { TabNav } from '@/components/TabNav';
import { useWatchData } from '@/hooks/useWatchData';
import type { WatchRecord } from '@/types';

const BRANDS = ['Patek Philippe', 'Rolex', 'Audemars Piguet', 'Richard Mille', 'Vacheron Constantin', 'Tudor', 'Cartier', 'A. Lange & S├╢hne', 'Unknown'];
const DIAL_COLORS = ['Black', 'Blue', 'Green', 'White', 'Brown', 'Grey', 'Champagne', 'Pink', 'Ice Blue', 'Purple', 'Yellow', 'Salmon', 'Red', 'Diamond', 'UNKNOWN'];
const CONDITIONS = ['New', 'Used', 'UNKNOWN'];
const VERDICTS = ['APPROVED', 'HUMAN', 'RECYCLE'];

type SortField = 'price' | 'confidence' | 'year' | 'reference';
type SortDir = 'asc' | 'desc';

export default function SearchPage() {
  const { records, loading, stats } = useWatchData();

  // Filters
  const [query, setQuery] = useState('');
  const [selectedBrands, setSelectedBrands] = useState<Set<string>>(new Set());
  const [selectedDials, setSelectedDials] = useState<Set<string>>(new Set());
  const [selectedConditions, setSelectedConditions] = useState<Set<string>>(new Set());
  const [selectedVerdicts, setSelectedVerdicts] = useState<Set<string>>(new Set());
  const [priceMin, setPriceMin] = useState('');
  const [priceMax, setPriceMax] = useState('');
  const [yearMin, setYearMin] = useState('');
  const [yearMax, setYearMax] = useState('');
  const [sortBy, setSortBy] = useState<SortField>('price');
  const [sortDir, setSortDir] = useState<SortDir>('desc');
  const [showFilters, setShowFilters] = useState(true);
  const [visibleCount, setVisibleCount] = useState(50);

  // Debounced search
  const [debouncedQuery, setDebouncedQuery] = useState('');
  const debounceRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  useEffect(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => setDebouncedQuery(query), 250);
    return () => { if (debounceRef.current) clearTimeout(debounceRef.current); };
  }, [query]);

  const toggleSet = (set: Set<string>, value: string, setter: (s: Set<string>) => void) => {
    const next = new Set(set);
    if (next.has(value)) next.delete(value); else next.add(value);
    setter(next);
    setVisibleCount(50);
  };

  const clearAll = () => {
    setQuery('');
    setSelectedBrands(new Set());
    setSelectedDials(new Set());
    setSelectedConditions(new Set());
    setSelectedVerdicts(new Set());
    setPriceMin(''); setPriceMax('');
    setYearMin(''); setYearMax('');
    setVisibleCount(50);
  };

  const filtered = useMemo(() => {
    let result = records;

    // Text search across reference, brand, rawMessage
    if (debouncedQuery.trim()) {
      const q = debouncedQuery.toLowerCase().trim();
      result = result.filter(r =>
        r.reference?.toLowerCase().includes(q) ||
        r.brand?.toLowerCase().includes(q) ||
        r.rawMessage?.toLowerCase().includes(q) ||
        r.dialColor?.toLowerCase().includes(q)
      );
    }

    if (selectedBrands.size > 0) {
      result = result.filter(r => selectedBrands.has(r.brand));
    }
    if (selectedDials.size > 0) {
      result = result.filter(r => selectedDials.has(r.dialColor));
    }
    if (selectedConditions.size > 0) {
      result = result.filter(r => selectedConditions.has(r.condition));
    }
    if (selectedVerdicts.size > 0) {
      result = result.filter(r => {
        // Derive verdict from confidence + isResidue (same logic as backend)
        let verdict: string;
        if (r.isResidue || r.confidence < 35) verdict = 'RECYCLE';
        else if (r.confidence >= 90 && !r.failureFlags?.length) verdict = 'APPROVED';
        else verdict = 'HUMAN';
        return selectedVerdicts.has(verdict);
      });
    }

    const pMin = parseFloat(priceMin);
    const pMax = parseFloat(priceMax);
    if (!isNaN(pMin)) result = result.filter(r => r.price >= pMin);
    if (!isNaN(pMax)) result = result.filter(r => r.price <= pMax);

    const yMin = parseInt(yearMin);
    const yMax = parseInt(yearMax);
    if (!isNaN(yMin)) result = result.filter(r => (r.year ?? 0) >= yMin);
    if (!isNaN(yMax)) result = result.filter(r => (r.year ?? 0) <= yMax);

    // Sort
    const dir = sortDir === 'asc' ? 1 : -1;
    result = [...result].sort((a, b) => {
      let av: number | string, bv: number | string;
      switch (sortBy) {
        case 'price': av = a.price; bv = b.price; break;
        case 'confidence': av = a.confidence; bv = b.confidence; break;
        case 'year': av = a.year ?? 0; bv = b.year ?? 0; break;
        case 'reference': av = a.reference; bv = b.reference; break;
        default: av = 0; bv = 0;
      }
      if (typeof av === 'string' && typeof bv === 'string') return av.localeCompare(bv) * dir;
      return ((av as number) - (bv as number)) * dir;
    });

    return result;
  }, [records, debouncedQuery, selectedBrands, selectedDials, selectedConditions, selectedVerdicts, priceMin, priceMax, yearMin, yearMax, sortBy, sortDir]);

  const visibleResults = filtered.slice(0, visibleCount);

  // Infinite scroll
  const sentinelRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const el = sentinelRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      (entries) => { if (entries[0].isIntersecting) setVisibleCount(c => Math.min(c + 50, filtered.length)); },
      { rootMargin: '200px' }
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [filtered.length]);

  const activeFilterCount = selectedBrands.size + selectedDials.size + selectedConditions.size + selectedVerdicts.size +
    (priceMin ? 1 : 0) + (priceMax ? 1 : 0) + (yearMin ? 1 : 0) + (yearMax ? 1 : 0);

  const formatPrice = (p: number) => p >= 1000000 ? `$${(p/1000000).toFixed(2)}M` : p >= 1000 ? `$${(p/1000).toFixed(0)}K` : `$${p}`;

  return (
    <Layout totalProcessed={stats.totalProcessed} normalizedCount={stats.normalizedCount} residueCount={stats.residueCount}>
      <TabNav totalProcessed={stats.totalProcessed} />
      <div className="max-w-7xl mx-auto px-5 py-6">
        {/* Search Bar */}
        <div className="flex gap-3 mb-4">
          <div className="relative flex-1">
            <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-text-muted" />
            <input
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search by reference, brand, dial color, or message textΓÇª"
              className="w-full pl-10 pr-4 py-3 bg-bg-card border border-border-default rounded-lg text-sm text-text-primary placeholder-text-muted focus:border-gold-primary focus:outline-none transition-colors"
            />
            {query && (
              <button onClick={() => setQuery('')} className="absolute right-3 top-1/2 -translate-y-1/2 text-text-muted hover:text-text-primary">
                <X size={16} />
              </button>
            )}
          </div>
          <button
            onClick={() => setShowFilters(!showFilters)}
            className={`flex items-center gap-2 px-4 py-3 rounded-lg text-xs font-semibold uppercase tracking-wider transition-colors ${
              activeFilterCount > 0 ? 'bg-gold-primary text-black' : 'bg-bg-card border border-border-default text-text-secondary hover:border-gold-primary'
            }`}
          >
            <Filter size={14} />
            Filters
            {activeFilterCount > 0 && <span className="bg-black/20 px-1.5 py-0.5 rounded text-[10px]">{activeFilterCount}</span>}
          </button>
          {(activeFilterCount > 0 || query) && (
            <button onClick={clearAll} className="px-3 py-3 rounded-lg text-xs font-semibold text-danger hover:bg-danger/10 transition-colors">
              Clear All
            </button>
          )}
        </div>

        {/* Filters Panel */}
        {showFilters && (
          <div className="mb-4 p-4 bg-bg-card border border-border-default rounded-lg space-y-4">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              {/* Brand */}
              <div>
                <label className="text-[10px] font-semibold uppercase tracking-wider text-text-muted block mb-2">Brand</label>
                <div className="flex flex-wrap gap-1">
                  {BRANDS.map(b => (
                    <button
                      key={b}
                      onClick={() => toggleSet(selectedBrands, b, setSelectedBrands)}
                      className={`px-2 py-1 text-[11px] rounded border transition-colors ${
                        selectedBrands.has(b) ? 'bg-gold-primary text-black border-gold-primary' : 'bg-bg-elevated text-text-secondary border-border-default hover:border-gold-primary/50'
                      }`}
                    >{b}</button>
                  ))}
                </div>
              </div>
              {/* Dial Color */}
              <div>
                <label className="text-[10px] font-semibold uppercase tracking-wider text-text-muted block mb-2">Dial Color</label>
                <div className="flex flex-wrap gap-1">
                  {DIAL_COLORS.map(d => (
                    <button
                      key={d}
                      onClick={() => toggleSet(selectedDials, d, setSelectedDials)}
                      className={`px-2 py-1 text-[11px] rounded border transition-colors ${
                        selectedDials.has(d) ? 'bg-gold-primary text-black border-gold-primary' : 'bg-bg-elevated text-text-secondary border-border-default hover:border-gold-primary/50'
                      }`}
                    >{d}</button>
                  ))}
                </div>
              </div>
              {/* Condition + Verdict */}
              <div className="space-y-3">
                <div>
                  <label className="text-[10px] font-semibold uppercase tracking-wider text-text-muted block mb-2">Condition</label>
                  <div className="flex flex-wrap gap-1">
                    {CONDITIONS.map(c => (
                      <button
                        key={c}
                        onClick={() => toggleSet(selectedConditions, c, setSelectedConditions)}
                        className={`px-2 py-1 text-[11px] rounded border transition-colors ${
                          selectedConditions.has(c) ? 'bg-gold-primary text-black border-gold-primary' : 'bg-bg-elevated text-text-secondary border-border-default hover:border-gold-primary/50'
                        }`}
                      >{c}</button>
                    ))}
                  </div>
                </div>
                <div>
                  <label className="text-[10px] font-semibold uppercase tracking-wider text-text-muted block mb-2">Verdict</label>
                  <div className="flex flex-wrap gap-1">
                    {VERDICTS.map(v => (
                      <button
                        key={v}
                        onClick={() => toggleSet(selectedVerdicts, v, setSelectedVerdicts)}
                        className={`px-2 py-1 text-[11px] rounded border transition-colors ${
                          selectedVerdicts.has(v) ? 'bg-gold-primary text-black border-gold-primary' : 'bg-bg-elevated text-text-secondary border-border-default hover:border-gold-primary/50'
                        }`}
                      >{v}</button>
                    ))}
                  </div>
                </div>
              </div>
              {/* Price + Year */}
              <div className="space-y-3">
                <div>
                  <label className="text-[10px] font-semibold uppercase tracking-wider text-text-muted block mb-2">Price (USD)</label>
                  <div className="flex gap-2 items-center">
                    <input type="number" value={priceMin} onChange={e => { setPriceMin(e.target.value); setVisibleCount(50); }} placeholder="Min" className="w-full px-2 py-1 text-[11px] bg-bg-elevated border border-border-default rounded text-text-primary focus:border-gold-primary focus:outline-none" />
                    <span className="text-text-muted text-[11px]">ΓÇö</span>
                    <input type="number" value={priceMax} onChange={e => { setPriceMax(e.target.value); setVisibleCount(50); }} placeholder="Max" className="w-full px-2 py-1 text-[11px] bg-bg-elevated border border-border-default rounded text-text-primary focus:border-gold-primary focus:outline-none" />
                  </div>
                </div>
                <div>
                  <label className="text-[10px] font-semibold uppercase tracking-wider text-text-muted block mb-2">Year</label>
                  <div className="flex gap-2 items-center">
                    <input type="number" value={yearMin} onChange={e => { setYearMin(e.target.value); setVisibleCount(50); }} placeholder="Min" className="w-full px-2 py-1 text-[11px] bg-bg-elevated border border-border-default rounded text-text-primary focus:border-gold-primary focus:outline-none" />
                    <span className="text-text-muted text-[11px]">ΓÇö</span>
                    <input type="number" value={yearMax} onChange={e => { setYearMax(e.target.value); setVisibleCount(50); }} placeholder="Max" className="w-full px-2 py-1 text-[11px] bg-bg-elevated border border-border-default rounded text-text-primary focus:border-gold-primary focus:outline-none" />
                  </div>
                </div>
              </div>
            </div>
            {/* Sort */}
            <div className="flex items-center gap-3 pt-2 border-t border-border-default">
              <span className="text-[10px] font-semibold uppercase tracking-wider text-text-muted">Sort by</span>
              {(['price', 'confidence', 'year', 'reference'] as SortField[]).map(field => (
                <button
                  key={field}
                  onClick={() => { setSortBy(field); setVisibleCount(50); }}
                  className={`px-2 py-1 text-[11px] rounded capitalize transition-colors ${sortBy === field ? 'text-gold-primary font-semibold' : 'text-text-muted hover:text-text-secondary'}`}
                >
                  {field}
                  {sortBy === field && <span className="ml-1">{sortDir === 'asc' ? 'Γåæ' : 'Γåô'}</span>}
                </button>
              ))}
              <button onClick={() => setSortDir(d => d === 'asc' ? 'desc' : 'asc')} className="ml-auto text-[11px] text-text-muted hover:text-text-secondary">
                {sortDir === 'asc' ? 'Ascending' : 'Descending'}
              </button>
            </div>
          </div>
        )}

        {/* Results count + Verdict Summary */}
        <div className="flex items-center justify-between mb-3 flex-wrap gap-3">
          <span className="text-xs text-text-muted">
            {loading ? 'Loading dataΓÇª' : `${filtered.length.toLocaleString()} results`}
            {filtered.length !== records.length && ` of ${records.length.toLocaleString()} total`}
          </span>
          {!loading && filtered.length > 0 && (
            <div className="flex gap-2">
              {(['APPROVED', 'HUMAN', 'RECYCLE'] as const).map(v => {
                const count = filtered.filter(r => {
                  if (r.isResidue || r.confidence < 35) return v === 'RECYCLE';
                  if (r.confidence >= 90 && !r.failureFlags?.length) return v === 'APPROVED';
                  return v === 'HUMAN';
                }).length;
                const colors = { APPROVED: 'text-success border-success/30 bg-success/10', HUMAN: 'text-warning border-warning/30 bg-warning/10', RECYCLE: 'text-danger border-danger/30 bg-danger/10' };
                return (
                  <button
                    key={v}
                    onClick={() => {
                      if (selectedVerdicts.has(v)) {
                        const next = new Set(selectedVerdicts); next.delete(v); setSelectedVerdicts(next);
                      } else {
                        setSelectedVerdicts(new Set([v]));
                      }
                      setVisibleCount(50);
                    }}
                    className={`px-2 py-1 text-[10px] font-semibold uppercase rounded border transition-all ${colors[v]} ${selectedVerdicts.has(v) ? 'ring-1 ring-current' : 'opacity-60 hover:opacity-100'}`}
                  >
                    {v} <span className="font-mono">{count.toLocaleString()}</span>
                  </button>
                );
              })}
            </div>
          )}
          {!loading && filtered.length > 0 && (
            <span className="text-[10px] text-text-muted">Showing {Math.min(visibleCount, filtered.length).toLocaleString()}</span>
          )}
        </div>

        {/* Results Table */}
        {!loading && filtered.length > 0 && (
          <div className="overflow-x-auto bg-bg-card border border-border-default rounded-lg">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-border-default text-[10px] uppercase tracking-wider text-text-muted">
                  <th className="text-left px-3 py-2 font-semibold">Reference</th>
                  <th className="text-left px-3 py-2 font-semibold">Brand</th>
                  <th className="text-left px-3 py-2 font-semibold">Dial</th>
                  <th className="text-right px-3 py-2 font-semibold">Price</th>
                  <th className="text-center px-3 py-2 font-semibold">Year</th>
                  <th className="text-center px-3 py-2 font-semibold">Conf</th>
                  <th className="text-center px-3 py-2 font-semibold">Verdict</th>
                  <th className="text-left px-3 py-2 font-semibold hidden lg:table-cell">Message</th>
                </tr>
              </thead>
              <tbody>
                {visibleResults.map((r) => {
                  let verdict: string;
                  if (r.isResidue || r.confidence < 35) verdict = 'RECYCLE';
                  else if (r.confidence >= 90 && !r.failureFlags?.length) verdict = 'APPROVED';
                  else verdict = 'HUMAN';
                  const verdictColor = verdict === 'APPROVED' ? 'text-success' : verdict === 'HUMAN' ? 'text-warning' : 'text-danger';
                  return (
                    <tr key={r.id} className="border-b border-border-default/50 hover:bg-bg-elevated/50 transition-colors">
                      <td className="px-3 py-2 font-mono text-xs text-gold-primary font-semibold">{r.reference}</td>
                      <td className="px-3 py-2 text-xs text-text-secondary">{r.brand}</td>
                      <td className="px-3 py-2 text-xs text-text-secondary">{r.dialColor}</td>
                      <td className="px-3 py-2 text-right font-mono text-xs text-text-primary">{formatPrice(r.price)}</td>
                      <td className="px-3 py-2 text-center text-xs text-text-muted">{r.year ?? 'ΓÇö'}</td>
                      <td className="px-3 py-2 text-center text-xs">
                        <span className={r.confidence >= 90 ? 'text-success' : r.confidence >= 80 ? 'text-warning' : 'text-danger'}>
                          {r.confidence}%
                        </span>
                      </td>
                      <td className="px-3 py-2 text-center text-[10px] font-semibold uppercase">
                        <span className={verdictColor}>{verdict}</span>
                      </td>
                      <td className="px-3 py-2 text-xs text-text-muted hidden lg:table-cell max-w-xs truncate">{r.rawMessage}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
            {/* Infinite scroll sentinel */}
            {visibleCount < filtered.length && (
              <div ref={sentinelRef} className="flex items-center justify-center py-6">
                <div className="w-8 h-8 border-2 border-gold-primary/30 border-t-gold-primary rounded-full animate-spin" />
              </div>
            )}
          </div>
        )}

        {/* No results */}
        {!loading && filtered.length === 0 && (
          <div className="flex flex-col items-center justify-center py-20 text-center">
            <Search size={48} className="text-text-muted/30 mb-4" />
            <p className="text-sm text-text-muted">No watches match your filters</p>
            <button onClick={clearAll} className="mt-4 px-4 py-2 text-xs text-gold-primary hover:underline">Clear all filters</button>
          </div>
        )}

        {/* Loading */}
        {loading && (
          <div className="flex flex-col items-center justify-center py-20">
            <div className="w-10 h-10 border-2 border-gold-primary/30 border-t-gold-primary rounded-full animate-spin mb-4" />
            <p className="text-xs text-text-muted">Loading 117K recordsΓÇª</p>
          </div>
        )}
      </div>
    </Layout>
  );
}

declare module 'xlsx-js-style' {
  const XLSX: any;
  export = XLSX;
}
